--

CREATE FUNCTION public.brief_is_live(p_status public.brief_status, p_publish_at timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  select p_status = 'published' or (p_status = 'scheduled' and p_publish_at is not null and p_publish_at <= now()) $$;


