-- Name: can_view_learner_performance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_view_learner_performance(p_participant uuid, p_cohort uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(
    is_staff()
    or (app_role() = 'trainer' and p_cohort in (select my_trainer_cohorts()))
    or (app_role() = 'mentor' and mentor_has_mentee(p_participant))
    or (app_role() = 'participant' and p_participant = my_participant_id()
        and learner_access_state(p_participant, p_cohort) in ('active', 'expired')),
    false) $$;


--
-- Name: cancel_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_email(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_staff() then raise exception 'Only programme management can cancel email'; end if;
  update email_outbox set status = 'cancelled' where id = p_id and status = 'queued';
  if not found then raise exception 'Only a queued email can be cancelled'; end if;
end $$;


--
-- Name: check_lesson_plan_timing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_lesson_plan_timing() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare sid uuid; problem text;
begin
  if tg_table_name = 'curriculum_sessions' then sid := new.id; else sid := new.session_id; end if;
  problem := lesson_plan_timing_problem(sid);
  if problem is not null then
    raise exception 'Lesson plan timing does not match the timetable: %', problem using errcode = 'check_violation';
  end if;
  return null;
end $$;


--
-- Name: check_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_request() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- Signed-out visitors and server calls (no user id) pass; RLS and grants still apply to them.
  if auth.uid() is not null and exists (select 1 from profiles p where p.id = auth.uid() and p.status <> 'active') then
    raise exception using errcode = '42501', message = 'DIRA_ACCOUNT_INACTIVE',
      hint = 'This account is not active. Contact the DIRA Foundation programme team.';
  end if;
end $$;


--
-- Name: FUNCTION check_request(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.check_request() IS 'PostgREST pre-request check (migration 34): refuses every Data API request from an inactive account.';


