--
-- Name: ci_cohort_comparison(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_cohort_comparison() RETURNS TABLE(cohort_id uuid, cohort_name text, track_id uuid, track_name text, level text, start_date date, learners integer, active_learners integer, withdrawn integer, avg_attendance numeric, submission_rate numeric, overdue integer, avg_tasks numeric, avg_final numeric, avg_overall numeric, results_count integer, requirements_met integer, certified integer, completion_rate numeric, needs_support integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with m as (
    select c.id as cohort_id, c.name as cohort_name, c.start_date, x.*
    from cohorts c cross join lateral _learner_metrics(c.id) x where ci_can_view()),
  grouped as (
    select cohort_id, cohort_name, start_date, track_id, track_name, grouping(track_id, track_name) as g,
      count(*)::int as learners,
      count(*) filter (where participant_status <> 'withdrawn')::int as active_learners,
      count(*) filter (where participant_status = 'withdrawn')::int as withdrawn,
      round(avg(attendance_rate) filter (where participant_status <> 'withdrawn'), 1) as avg_attendance,
      case when sum(assignments_expected) filter (where participant_status <> 'withdrawn') > 0
           then round(100.0 * sum(submitted) filter (where participant_status <> 'withdrawn') / sum(assignments_expected) filter (where participant_status <> 'withdrawn'), 1) end as submission_rate,
      coalesce(sum(overdue) filter (where participant_status <> 'withdrawn'), 0)::int as overdue,
      round(avg(tasks_pct) filter (where participant_status <> 'withdrawn'), 1) as avg_tasks,
      round(avg(final_pct) filter (where participant_status <> 'withdrawn'), 1) as avg_final,
      round(avg(overall) filter (where participant_status <> 'withdrawn'), 1) as avg_overall,
      count(overall) filter (where participant_status <> 'withdrawn')::int as results_count,
      count(*) filter (where completion_status = 'requirements_met')::int as requirements_met,
      count(*) filter (where completion_status = 'certified')::int as certified,
      case when count(*) filter (where participant_status <> 'withdrawn') > 0
           then round(100.0 * count(*) filter (where completion_status in ('requirements_met', 'certified')) / count(*) filter (where participant_status <> 'withdrawn'), 1) end as completion_rate,
      count(*) filter (where needs_support)::int as needs_support
    from m group by grouping sets ((cohort_id, cohort_name, start_date), (cohort_id, cohort_name, start_date, track_id, track_name)))
  select cohort_id, cohort_name, track_id, case when g = 0 then coalesce(track_name, 'No track yet') end, case when g = 0 then 'track' else 'cohort' end, start_date,
    learners, active_learners, withdrawn, avg_attendance, submission_rate, overdue, avg_tasks, avg_final, avg_overall, results_count,
    requirements_met, certified, completion_rate, needs_support
  from grouped order by start_date desc, cohort_name, g desc, track_name nulls first $$;


--
-- Name: ci_facilitators(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_facilitators() RETURNS TABLE(trainer_id uuid, trainer_name text, cohort_id uuid, cohort_name text, sessions_scheduled integer, sessions_completed integer, sessions_cancelled integer, reports_filed integer, learners integer, avg_attendance numeric, awaiting_grading integer, graded_with_time integer, avg_turnaround_hours numeric, feedback_notes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select ta.trainer_id, btrim(p.first_name || ' ' || p.last_name), c.id, c.name,
    (select count(*)::int from session_schedules s where s.cohort_id = c.id and s.trainer_id = ta.trainer_id),
    (select count(*)::int from session_schedules s where s.cohort_id = c.id and s.trainer_id = ta.trainer_id and s.status = 'completed'),
    (select count(*)::int from session_schedules s where s.cohort_id = c.id and s.trainer_id = ta.trainer_id and s.status = 'cancelled'),
    (select count(*)::int from session_schedules s join session_reports r on r.schedule_id = s.id where s.cohort_id = c.id and s.trainer_id = ta.trainer_id),
    (select count(*)::int from cohort_enrolments e where e.cohort_id = c.id),
    (select round(avg(x.attendance_rate) filter (where x.participant_status <> 'withdrawn'), 1) from _learner_metrics(c.id) x),
    -- latest attempts in this cohort waiting for a grade
    (select count(*)::int from submissions sb join assignments a on a.id = sb.assignment_id
      where a.cohort_id = c.id and sb.status in ('submitted', 'late')
        and not exists (select 1 from submissions n where n.assignment_id = sb.assignment_id and n.participant_id = sb.participant_id and n.attempt > sb.attempt)),
    (select count(*)::int from submissions sb join assignments a on a.id = sb.assignment_id where a.cohort_id = c.id and sb.graded_by = ta.trainer_id and sb.graded_at is not null),
    (select round(avg(extract(epoch from (sb.graded_at - sb.submitted_at)) / 3600)::numeric, 1) from submissions sb join assignments a on a.id = sb.assignment_id
      where a.cohort_id = c.id and sb.graded_by = ta.trainer_id and sb.graded_at is not null),
    (select count(*)::int from learner_feedback f where f.cohort_id = c.id and f.author_id = ta.trainer_id)
  from trainer_assignments ta join cohorts c on c.id = ta.cohort_id join profiles p on p.id = ta.trainer_id
  where is_staff() or (app_role() = 'trainer' and ta.trainer_id = auth.uid())
  order by c.start_date desc, 2 $$;


--
-- Name: ci_intake(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_intake() RETURNS TABLE(cohort_id uuid, cohort_name text, intake_label text, season text, start_date date, end_date date, recruitment_opens_on date, recruitment_closes_on date, capacity integer, enrolled integer, withdrawn integer, fill_pct numeric, tracks jsonb, applications_in_window integer, accepted_in_window integer, rejected_in_window integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.intake_label, c.season, c.start_date, c.end_date, c.recruitment_opens_on, c.recruitment_closes_on, c.capacity,
    (select count(*)::int from cohort_enrolments e where e.cohort_id = c.id),
    (select count(*)::int from cohort_enrolments e join participants p on p.id = e.participant_id where e.cohort_id = c.id and p.status = 'withdrawn'),
    case when c.capacity > 0 then round(100.0 * (select count(*) from cohort_enrolments e where e.cohort_id = c.id) / c.capacity, 1) end,
    coalesce((select jsonb_agg(jsonb_build_object('track', coalesce(t.name, 'No track yet'), 'learners', x.n) order by t.position nulls last)
              from (select e.track_id, count(*)::int as n from cohort_enrolments e where e.cohort_id = c.id group by e.track_id) x
              left join tracks t on t.id = x.track_id), '[]'::jsonb),
    -- applications are programme-wide, not tied to a cohort: counted by submission date inside the recruitment window
    case when is_staff() and c.recruitment_opens_on is not null and c.recruitment_closes_on is not null then
      (select count(*)::int from applications a where a.programme_id = c.programme_id and a.status <> 'draft'
         and a.submitted_at >= c.recruitment_opens_on and a.submitted_at < c.recruitment_closes_on + 1) end,
    case when is_staff() and c.recruitment_opens_on is not null and c.recruitment_closes_on is not null then
      (select count(*)::int from applications a where a.programme_id = c.programme_id and a.status = 'accepted'
         and a.submitted_at >= c.recruitment_opens_on and a.submitted_at < c.recruitment_closes_on + 1) end,
    case when is_staff() and c.recruitment_opens_on is not null and c.recruitment_closes_on is not null then
      (select count(*)::int from applications a where a.programme_id = c.programme_id and a.status = 'rejected'
         and a.submitted_at >= c.recruitment_opens_on and a.submitted_at < c.recruitment_closes_on + 1) end
  from cohorts c where ci_can_view() order by c.start_date desc $$;


--
-- Name: ci_learners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_learners() RETURNS TABLE(cohort_id uuid, cohort_name text, participant_id uuid, participant_no text, display_name text, track_name text, participant_status text, access_status text, attendance_rate numeric, submitted integer, assignments_expected integer, overdue integer, overall numeric, completion_status text, needs_support boolean, support_reasons text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, x.participant_id, x.participant_no, x.display_name, x.track_name, x.participant_status, x.access_status, x.attendance_rate,
         x.submitted, x.assignments_expected, x.overdue, x.overall, x.completion_status, x.needs_support, x.support_reasons
  from cohorts c cross join lateral _learner_metrics(c.id) x
  where is_staff() order by c.start_date desc, x.display_name $$;


--
-- Name: ci_safeguarding_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_safeguarding_summary() RETURNS TABLE(cohort_name text, open_count integer, acknowledged_or_active integer, resolved_or_closed integer, urgent integer, overdue_ack integer, legal_holds integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with r as (
    select s.*, (select co.name from cohort_enrolments e join cohorts co on co.id = e.cohort_id where e.participant_id = s.participant_id order by co.start_date desc limit 1) as cohort_name
    from safeguarding_records s where is_safeguarding_officer())
  select coalesce(cohort_name, 'Not linked to a learner'),
    count(*) filter (where status = 'open')::int,
    count(*) filter (where status in ('acknowledged', 'in_progress', 'referred', 'under_review'))::int,
    count(*) filter (where status in ('resolved', 'closed'))::int,
    count(*) filter (where urgency = 'urgent')::int,
    count(*) filter (where status = 'open' and acknowledged_at is null and ack_due_at < now())::int,
    count(*) filter (where legal_hold)::int
  from r group by 1 order by 1 $$;


--
-- Name: ci_support(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ci_support() RETURNS TABLE(cohort_id uuid, cohort_name text, learners integer, needs_support integer, low_attendance integer, with_overdue_work integer, with_returned_work integer, access_scheduled integer, access_expired integer, access_suspended integer, reports_open integer, reports_escalated integer, reports_closed integer, active_mutes integer, closed_access_support_messages_30d integer, feedback_notes integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, count(x.participant_id)::int,
    count(*) filter (where x.needs_support)::int,
    count(*) filter (where 'attendance' = any(x.support_reasons))::int,
    count(*) filter (where 'overdue_work' = any(x.support_reasons))::int,
    count(*) filter (where 'work_returned' = any(x.support_reasons))::int,
    count(*) filter (where x.access_status in ('scheduled', 'pending'))::int,
    count(*) filter (where x.access_status = 'expired')::int,
    count(*) filter (where x.access_status = 'suspended')::int,
    (select count(*)::int from connect_reports r join connect_conversations cv on cv.id = r.conversation_id
      where r.status = 'open' and (cv.cohort_id = c.id or cv.learner_id in (select e.participant_id from cohort_enrolments e where e.cohort_id = c.id))),
    (select count(*)::int from connect_reports r join connect_conversations cv on cv.id = r.conversation_id
      where r.status = 'escalated' and (cv.cohort_id = c.id or cv.learner_id in (select e.participant_id from cohort_enrolments e where e.cohort_id = c.id))),
    (select count(*)::int from connect_reports r join connect_conversations cv on cv.id = r.conversation_id
      where r.status in ('dismissed', 'hidden') and (cv.cohort_id = c.id or cv.learner_id in (select e.participant_id from cohort_enrolments e where e.cohort_id = c.id))),
    (select count(*)::int from connect_mutes mu join participants pa on pa.profile_id = mu.profile_id join cohort_enrolments e on e.participant_id = pa.id
      where e.cohort_id = c.id and mu.until > now()),
    -- private (not safeguarding) messages sent in the last 30 days by learners whose access to this cohort is not active
    (select count(*)::int from connect_messages m join connect_conversations cv on cv.id = m.conversation_id and cv.kind = 'direct'
      join participants pa on pa.id = cv.learner_id
      where m.sender_id = pa.profile_id and m.created_at > now() - interval '30 days'
        and exists (select 1 from cohort_enrolments e where e.cohort_id = c.id and e.participant_id = pa.id)
        and learner_access_state(pa.id, c.id) <> 'active'),
    (select count(*)::int from learner_feedback f where f.cohort_id = c.id)
  from cohorts c left join lateral _learner_metrics(c.id) x on true
  where ci_can_view() group by c.id, c.name, c.start_date order by c.start_date desc $$;




--
-- Name: email_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.email_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    to_user_id uuid,
    to_email text NOT NULL,
    template_key text,
    campaign text,
    subject text NOT NULL,
    body text NOT NULL,
    status public.email_status DEFAULT 'queued'::public.email_status NOT NULL,
    scheduled_for timestamp with time zone DEFAULT now() NOT NULL,
    attempts integer DEFAULT 0 NOT NULL,
    provider_id text,
    error text,
    sent_at timestamp with time zone,
    claimed_at timestamp with time zone,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: claim_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_emails(p_limit integer DEFAULT 25) RETURNS SETOF public.email_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  update email_outbox set status = 'sending', attempts = attempts + 1, claimed_at = now()
  where id in (select id from email_outbox where status = 'queued' and scheduled_for <= now() and attempts < 3 order by scheduled_for limit greatest(1, least(p_limit, 100)) for update skip locked)
  returning *;
end $$;


--
-- Name: claim_file_scans(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_file_scans(p_limit integer DEFAULT 10) RETURNS TABLE(bucket_id text, object_name text, object_updated_at timestamp with time zone, mime_type text, size_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  -- new or re-uploaded files enter the queue
  insert into storage_file_scans as s (bucket_id, object_name, object_updated_at, status, uploaded_by)
  select o.bucket_id, o.name, o.updated_at, 'pending', o.owner from storage.objects o
  where scanned_bucket(o.bucket_id) and o.updated_at is not null
    and not exists (select 1 from storage_file_scans x where x.bucket_id = o.bucket_id and x.object_name = o.name and x.object_updated_at = o.updated_at)
  on conflict on constraint storage_file_scans_pkey do update
    set object_updated_at = excluded.object_updated_at, status = 'pending', attempts = 0, claimed_at = null, scanned_at = null,
        engine = null, detail = null, uploaded_by = excluded.uploaded_by;
  return query
  with c as (
    select s.bucket_id, s.object_name from storage_file_scans s
    where s.status = 'pending' or (s.status = 'scanning' and s.claimed_at < now() - interval '15 minutes')
    order by s.object_updated_at limit greatest(1, least(p_limit, 50)) for update skip locked)
  update storage_file_scans s set status = 'scanning', claimed_at = now(), attempts = s.attempts + 1
  from c, storage.objects o
  where s.bucket_id = c.bucket_id and s.object_name = c.object_name and o.bucket_id = s.bucket_id and o.name = s.object_name
  returning s.bucket_id, s.object_name, s.object_updated_at, (o.metadata ->> 'mimetype'), nullif(o.metadata ->> 'size', '')::bigint;
end $$;


--
-- Name: claim_first_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_first_admin(p_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare changed int;
begin
  perform pg_advisory_xact_lock(hashtext('dira_claim_first_admin'));
  if exists (select 1 from profiles where role = 'super_admin' and status = 'active') then return false; end if;
  update profiles set role = 'super_admin', status = 'active' where id = p_user and role = 'applicant';
  get diagnostics changed = row_count;
  return changed = 1;
end $$;


--
-- Name: cohort_access_roster(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cohort_access_roster(p_cohort uuid) RETURNS TABLE(participant_id uuid, participant_no text, learner_name text, status public.learner_access_status, opens_at timestamp with time zone, closes_at timestamp with time zone, has_override boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select p.id, p.participant_no, btrim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')),
         learner_access_state(p.id, e.cohort_id),
         coalesce(a.opens_at_override, c.access_opens_at), coalesce(a.closes_at_override, c.access_closes_at),
         (a.opens_at_override is not null or a.closes_at_override is not null)
  from cohort_enrolments e
  join cohorts c on c.id = e.cohort_id
  join participants p on p.id = e.participant_id
  join profiles pr on pr.id = p.profile_id
  left join learner_access a on a.participant_id = p.id and a.cohort_id = e.cohort_id
  where e.cohort_id = p_cohort and is_staff()
  order by pr.last_name, pr.first_name $$;


--
-- Name: complete_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_session(p_schedule uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s record; tid uuid; missing int;
begin
  if not can_manage_schedule(p_schedule) then raise exception 'You cannot manage this session'; end if;
  select ss.*, cs.track_id as session_track into s from session_schedules ss join curriculum_sessions cs on cs.id = ss.curriculum_session_id
    where ss.id = p_schedule for update of ss;
  if s.id is null then raise exception 'Session not found'; end if;
  if s.status <> 'scheduled' then raise exception 'Only a scheduled session can be completed (this one is %)', s.status; end if;
  if s.starts_at > now() then raise exception 'This session has not started yet'; end if;
  select count(*) into missing from cohort_enrolments e
    where e.cohort_id = s.cohort_id and (s.session_track is null or e.track_id = s.session_track)
      and not exists (select 1 from attendance a where a.schedule_id = p_schedule and a.participant_id = e.participant_id);
  if missing > 0 then raise exception 'Attendance is missing for % participant(s)', missing; end if;
  update session_schedules set status = 'completed' where id = p_schedule;
end $$;


--
-- Name: connect_allowed_mime(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_allowed_mime(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  select p in ('application/pdf', 'image/jpeg', 'image/png', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
               'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'application/vnd.openxmlformats-officedocument.presentationml.presentation') $$;


--
-- Name: connect_attachment_read_ok(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_attachment_read_ok(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select connect_attachment_visible(p_name) and exists (select 1 from connect_attachments a where a.storage_path = p_name and a.scan_status = 'clean') $$;


--
-- Name: connect_attachment_upload_ok(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_attachment_upload_ok(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare parts text[] := string_to_array(p_name, '/'); conv uuid;
begin
  if array_length(parts, 1) <> 3 or parts[2] is distinct from auth.uid()::text then return false; end if;
  begin conv := parts[1]::uuid; exception when others then return false; end;
  return connect_can_post(conv);
end $$;


--
-- Name: connect_attachment_visible(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_attachment_visible(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from connect_attachments a join connect_messages m on m.id = a.message_id
                 where a.storage_path = p_name and a.scan_status <> 'infected'
                   and ((m.hidden_at is null and connect_can_see(a.conversation_id))
                        or exists (select 1 from connect_oversight_log l where l.profile_id = auth.uid() and l.conversation_id = a.conversation_id
                                   and l.created_at > now() - interval '1 hour'))) $$;


--
-- Name: connect_can_post(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_can_post(p_conv uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select not c.locked and connect_is_member(p_conv) and case c.kind
      when 'cohort' then app_role() in ('participant', 'trainer')
        and (app_role() <> 'participant' or learner_access_state(my_participant_id(), c.cohort_id) = 'active')
        and not exists (select 1 from connect_mutes m where m.profile_id = auth.uid() and m.until > now())
      when 'direct' then app_role() in ('participant', 'trainer')
      else true end
    from connect_conversations c where c.id = p_conv), false) $$;


--
-- Name: connect_can_see(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_can_see(p_conv uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select case
      when connect_is_member(p_conv) then
        c.kind <> 'cohort' or app_role() <> 'participant' or learner_access_state(my_participant_id(), c.cohort_id) = 'active'
      else c.kind = 'cohort' and connect_is_discussion_overseer()
    end
    from connect_conversations c where c.id = p_conv), false) $$;


--
-- Name: connect_claim_scans(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_claim_scans(p_limit integer DEFAULT 10) RETURNS TABLE(attachment_id uuid, storage_path text, file_name text, mime_type text, size_bytes bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return query
  with c as (
    select a.id from connect_attachments a
    where a.scan_status = 'pending' or (a.scan_status = 'scanning' and a.scan_claimed_at < now() - interval '15 minutes')
    order by a.created_at limit greatest(1, least(p_limit, 50)) for update skip locked)
  update connect_attachments a set scan_status = 'scanning', scan_claimed_at = now(), scan_attempts = a.scan_attempts + 1
  from c where a.id = c.id
  returning a.id, a.storage_path, a.file_name, a.mime_type, a.size_bytes;
end $$;


--
-- Name: connect_facilitator_assigned(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_facilitator_assigned(p_learner uuid, p_facilitator uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from trainer_assignments ta
                 join cohort_enrolments e on e.cohort_id = ta.cohort_id
                 join profiles f on f.id = ta.trainer_id and f.status = 'active' and f.role = 'trainer'
                 where ta.trainer_id = p_facilitator and e.participant_id = p_learner) $$;


--
-- Name: connect_handle_report(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_handle_report(p_report uuid, p_action text, p_note text DEFAULT NULL::text, p_urgency text DEFAULT 'standard'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r connect_reports; c connect_conversations; learner uuid;
begin
  if not connect_is_moderator() then raise exception 'Only moderators can handle reports'; end if;
  if p_action not in ('dismiss', 'hide', 'escalate') then raise exception 'Unknown action'; end if;
  select * into r from connect_reports where id = p_report;
  if not found then raise exception 'Report not found'; end if;
  if p_action = 'hide' then
    insert into connect_hidden_originals(message_id, body, hidden_by) select m.id, m.body, auth.uid() from connect_messages m where m.id = r.message_id and m.hidden_at is null on conflict do nothing;
    update connect_messages set body = 'This message was removed by a moderator.', hidden_at = now(), hidden_by = auth.uid(), hide_reason = nullif(btrim(coalesce(p_note, '')), '') where id = r.message_id and hidden_at is null;
  end if;
  if p_action = 'escalate' then
    if r.status = 'escalated' then raise exception 'This report is already with safeguarding'; end if;
    if p_urgency not in ('urgent', 'standard') then raise exception 'Choose urgent or standard'; end if;
    perform sg_escalate_report(r.id, p_urgency, coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Escalated from a DIRA Connect report'), 'connect_report');
    return;
  end if;
  if r.status = 'escalated' then
    if p_action = 'dismiss' then raise exception 'An escalated report is handled by safeguarding and cannot be dismissed'; end if;
    return;  -- hiding an escalated message keeps the report with safeguarding
  end if;
  update connect_reports set status = case p_action when 'dismiss' then 'dismissed' else 'hidden' end,
         handled_by = auth.uid(), handled_at = now(), handler_note = nullif(btrim(coalesce(p_note, '')), '') where id = p_report;
end $$;


--
-- Name: connect_is_discussion_overseer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_is_discussion_overseer() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(is_executive() or exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'discussions'), false) $$;


--
-- Name: connect_is_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_is_member(p_conv uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce((
    select case c.kind
      when 'direct' then
        (c.learner_id = my_participant_id() and app_role() = 'participant')
        or (c.facilitator_id = auth.uid() and app_role() = 'trainer' and connect_facilitator_assigned(c.learner_id, c.facilitator_id))
      when 'safeguarding' then
        (c.learner_id = my_participant_id() and app_role() = 'participant') or is_safeguarding_officer()
      else
        (app_role() = 'trainer' and c.cohort_id in (select my_trainer_cohorts()))
        or (app_role() = 'participant' and exists (select 1 from cohort_enrolments e where e.cohort_id = c.cohort_id and e.participant_id = my_participant_id()))
    end
    from connect_conversations c where c.id = p_conv), false) $$;


--
-- Name: connect_is_moderator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_is_moderator() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(is_executive() or exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'reports'), false) $$;


--
-- Name: connect_list_reports(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_list_reports(p_status text DEFAULT 'open'::text) RETURNS TABLE(id uuid, created_at timestamp with time zone, reason text, note text, snapshot_body text, sender_id uuid, sender_name text, conversation_id uuid, conversation_kind text, conversation_title text, status text, handler_note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.id, r.created_at, r.reason, r.note, r.snapshot_body, r.snapshot_sender, btrim(sp.first_name || ' ' || sp.last_name), r.conversation_id, c.kind,
         case c.kind when 'cohort' then (select name from cohorts where id = c.cohort_id) else 'Private conversation' end, r.status, r.handler_note
  from connect_reports r join connect_conversations c on c.id = r.conversation_id join profiles sp on sp.id = r.snapshot_sender
  where connect_is_moderator() and (p_status = 'all' or r.status = p_status) order by r.created_at desc limit 200 $$;


--
-- Name: connect_mark_read(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_mark_read(p_conversation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not connect_can_see(p_conversation) then return; end if;
  insert into connect_reads(conversation_id, profile_id, last_read_at) values (p_conversation, auth.uid(), now())
  on conflict (conversation_id, profile_id) do update set last_read_at = now();
end $$;


--
-- Name: connect_mute(uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_mute(p_profile uuid, p_until timestamp with time zone, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not connect_is_moderator() then raise exception 'Only moderators can mute'; end if;
  if p_until <= now() then raise exception 'Choose a future time'; end if;
  if not exists (select 1 from profiles where id = p_profile and role in ('participant', 'trainer')) then raise exception 'Only learners and facilitators can be muted'; end if;
  insert into connect_mutes(profile_id, until, reason, muted_by) values (p_profile, p_until, btrim(p_reason), auth.uid())
  on conflict (profile_id) do update set until = excluded.until, reason = excluded.reason, muted_by = auth.uid(), created_at = now();
end $$;


--
-- Name: connect_my_facilitators(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_my_facilitators() RETURNS TABLE(profile_id uuid, display_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select distinct p.id, btrim(p.first_name || ' ' || p.last_name)
  from cohort_enrolments e join trainer_assignments ta on ta.cohort_id = e.cohort_id join profiles p on p.id = ta.trainer_id
  where app_role() = 'participant' and e.participant_id = my_participant_id() and p.role = 'trainer' and p.status = 'active' $$;


--
-- Name: connect_my_learners(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_my_learners() RETURNS TABLE(participant_id uuid, display_name text, cohort_names text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select pa.id, btrim(p.first_name || ' ' || p.last_name), string_agg(distinct co.name, ', ')
  from trainer_assignments ta join cohort_enrolments e on e.cohort_id = ta.cohort_id join cohorts co on co.id = e.cohort_id
  join participants pa on pa.id = e.participant_id join profiles p on p.id = pa.profile_id
  where app_role() = 'trainer' and ta.trainer_id = auth.uid() and p.status = 'active'
  group by pa.id, p.first_name, p.last_name order by 2 $$;


--
-- Name: connect_my_support(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_my_support() RETURNS TABLE(safeguarding_available boolean, learning_access_open boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select sg_acting_officer() is not null, participant_access_active() where app_role() = 'participant' $$;


--
-- Name: connect_oversight_read(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_oversight_read(p_conversation uuid, p_reason text, p_safeguarding_record uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, sender_name text, body text, created_at timestamp with time zone, hidden boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare has_grant boolean; officer boolean; reported boolean; escalated boolean; b text;
begin
  has_grant := exists (select 1 from connect_oversight o where o.profile_id = auth.uid() and o.scope = 'private');
  officer := is_safeguarding_officer();
  if not (has_grant or officer) then raise exception 'You have not been granted private conversation oversight'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'A written reason of at least 10 characters is required'; end if;
  if not exists (select 1 from connect_conversations c where c.id = p_conversation and c.kind = 'direct') then raise exception 'Not a private conversation'; end if;
  escalated := exists (select 1 from connect_reports r where r.conversation_id = p_conversation and r.status = 'escalated')
            or exists (select 1 from safeguarding_records s where s.conversation_id = p_conversation);
  reported := exists (select 1 from connect_reports r where r.conversation_id = p_conversation);
  if p_safeguarding_record is not null then
    if not sg_is_acting_lead() then raise exception 'Only the acting Safeguarding Lead can open a conversation for a safeguarding record'; end if;
    if not exists (select 1 from safeguarding_records s where s.id = p_safeguarding_record and s.status not in ('resolved', 'closed')) then
      raise exception 'Name an open safeguarding record';
    end if;
    b := 'safeguarding_concern';
  elsif escalated then b := 'escalated_conversation';
  elsif reported then b := 'reported_conversation';
  else raise exception 'This conversation has not been reported or escalated. The acting Safeguarding Lead can open it only for a documented safeguarding record';
  end if;
  insert into connect_oversight_log(profile_id, conversation_id, reason, basis, safeguarding_record_id) values (auth.uid(), p_conversation, btrim(p_reason), b, p_safeguarding_record);
  if officer then
    insert into safeguarding_access_log(profile_id, record_id, conversation_id, basis, reason) values (auth.uid(), p_safeguarding_record, p_conversation, b, btrim(p_reason));
  end if;
  if p_safeguarding_record is not null then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (p_safeguarding_record, 'conversation_read', btrim(p_reason), auth.uid());
  end if;
  return query select m.id, btrim(pr.first_name || ' ' || pr.last_name), coalesce(h.body, m.body), m.created_at, (m.hidden_at is not null)
    from connect_messages m join profiles pr on pr.id = m.sender_id left join connect_hidden_originals h on h.message_id = m.id
    where m.conversation_id = p_conversation order by m.created_at desc limit 200;
end $$;


--
-- Name: connect_place_hold(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_place_hold(p_conversation uuid, p_participant uuid, p_cohort uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare hid uuid;
begin
  if not (is_executive() or is_safeguarding_officer()) then raise exception 'Only executives and safeguarding officers can place a legal hold'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  insert into connect_legal_holds(conversation_id, participant_id, cohort_id, reason, placed_by) values (p_conversation, p_participant, p_cohort, btrim(p_reason), auth.uid()) returning id into hid;
  return hid;
end $$;


--
-- Name: connect_record_scan(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_record_scan(p_attachment uuid, p_result text, p_engine text DEFAULT NULL::text, p_detail text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a connect_attachments; final text;
begin
  if p_result not in ('clean', 'infected', 'error') then raise exception 'Result must be clean, infected or error'; end if;
  select * into a from connect_attachments where id = p_attachment for update;
  if not found then raise exception 'Attachment not found'; end if;
  final := case p_result when 'error' then (case when a.scan_attempts >= 3 then 'scan_failed' else 'pending' end) else p_result end;
  update connect_attachments set scan_status = final, scanned_at = case when p_result = 'error' then scanned_at else now() end,
         scan_engine = coalesce(left(p_engine, 100), scan_engine), scan_detail = left(p_detail, 500), scan_claimed_at = null where id = p_attachment;
  insert into connect_attachment_scans(attachment_id, result, engine, detail) values (p_attachment, p_result, left(p_engine, 100), left(p_detail, 500));
  if final = 'infected' then
    -- the sender is told their file was blocked; moderators can see it in the scan log
    insert into notifications(user_id, kind, title, body) values (a.uploaded_by, 'message', 'A file you shared was blocked', 'Our virus check found a problem with ' || left(a.file_name, 100) || '. It cannot be opened.');
  end if;
  return final;
end $$;


--
-- Name: connect_release_hold(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_release_hold(p_hold uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not (is_executive() or is_safeguarding_officer()) then raise exception 'Only executives and safeguarding officers can release a legal hold'; end if;
  if p_reason is null or length(btrim(p_reason)) < 10 then raise exception 'Write a reason of at least 10 characters'; end if;
  update connect_legal_holds set released_at = now(), released_by = auth.uid(), release_reason = btrim(p_reason) where id = p_hold and released_at is null;
  if not found then raise exception 'That hold is not active'; end if;
end $$;


--
-- Name: connect_report_message(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_report_message(p_message uuid, p_reason text, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m connect_messages; files text;
begin
  select * into m from connect_messages where id = p_message;
  if not found or not connect_is_member(m.conversation_id) or not connect_can_see(m.conversation_id) then raise exception 'You can only report messages in your own conversations'; end if;
  if (select kind from connect_conversations where id = m.conversation_id) = 'safeguarding' then
    raise exception 'Safeguarding conversations cannot be reported to moderators. Please contact DIRA Foundation directly about any concern';
  end if;
  if m.sender_id = auth.uid() then raise exception 'You cannot report your own message'; end if;
  select string_agg(a.file_name, ', ') into files from connect_attachments a where a.message_id = m.id;
  insert into connect_reports(message_id, conversation_id, reporter_id, reason, note, snapshot_body, snapshot_sender)
  values (m.id, m.conversation_id, auth.uid(), p_reason, nullif(btrim(coalesce(p_note, '')), ''), m.body || coalesce(E'\n[Attachments: ' || files || ']', ''), m.sender_id)
  on conflict (message_id, reporter_id) do nothing;
end $$;


--
-- Name: connect_retention_candidates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_retention_candidates() RETURNS TABLE(conversation_id uuid, kind text, ends_on date, purge_after date, held boolean, hold_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with s as (select months from connect_retention_settings limit 1),
  base as (
    select c.id, c.kind, c.learner_id, c.cohort_id,
           case when c.kind = 'cohort' then (select co.end_date from cohorts co where co.id = c.cohort_id)
                else (select max(co.end_date) from cohort_enrolments e join cohorts co on co.id = e.cohort_id where e.participant_id = c.learner_id) end as ends_on
    from connect_conversations c)
  select b.id, b.kind, b.ends_on, (b.ends_on + make_interval(months => (select months from s)))::date,
         h.reason is not null, h.reason
  from base b
  left join lateral (select case
      when b.kind = 'safeguarding' then 'Safeguarding conversation (separate retention policy)'
      when exists (select 1 from connect_reports r where r.conversation_id = b.id) then 'Contains a reported message'
      when exists (select 1 from safeguarding_records sr where sr.conversation_id = b.id or (b.learner_id is not null and sr.participant_id = b.learner_id)) then 'Linked to a safeguarding record'
      when exists (select 1 from connect_legal_holds lh where lh.released_at is null and (lh.conversation_id = b.id
                     or (b.learner_id is not null and lh.participant_id = b.learner_id)
                     or lh.cohort_id = b.cohort_id
                     or (b.learner_id is not null and lh.cohort_id in (select e.cohort_id from cohort_enrolments e where e.participant_id = b.learner_id)))) then 'Legal hold'
    end as reason) h on true $$;


--
-- Name: connect_retention_purge(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_retention_purge() RETURNS TABLE(storage_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare en boolean; cv record; nconv int := 0; nmsg int := 0; nfile int := 0; paths text[] := '{}'; k int;
begin
  select enabled into en from connect_retention_settings limit 1;
  if not coalesce(en, false) then return; end if;
  perform set_config('dira.connect_purge', 'on', true);
  for cv in select r.conversation_id from connect_retention_candidates() r where r.purge_after <= current_date and not r.held loop
    paths := paths || coalesce(array(select a.storage_path from connect_attachments a where a.conversation_id = cv.conversation_id), '{}');
    delete from connect_attachments a where a.conversation_id = cv.conversation_id; get diagnostics k = row_count; nfile := nfile + k;
    delete from connect_reads r where r.conversation_id = cv.conversation_id;
    delete from connect_messages m where m.conversation_id = cv.conversation_id; get diagnostics k = row_count;
    if k > 0 then nconv := nconv + 1; nmsg := nmsg + k; end if;
  end loop;
  perform set_config('dira.connect_purge', 'off', true);
  if nconv > 0 then insert into connect_retention_log(conversations, messages, files) values (nconv, nmsg, nfile); end if;
  return query select unnest(paths);
end $$;


--
-- Name: connect_retention_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_retention_status() RETURNS TABLE(conversation_id uuid, kind text, messages bigint, ends_on date, purge_after date, due boolean, held boolean, hold_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select r.conversation_id, r.kind, (select count(*) from connect_messages m where m.conversation_id = r.conversation_id),
         r.ends_on, r.purge_after, coalesce(r.purge_after <= current_date, false), r.held, r.hold_reason
  from connect_retention_candidates() r
  where (is_executive() or is_safeguarding_officer()) and exists (select 1 from connect_messages m where m.conversation_id = r.conversation_id)
  order by r.purge_after nulls last $$;


--
-- Name: connect_scan_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_scan_queue() RETURNS TABLE(pending integer, scanning integer, clean integer, infected integer, scan_failed integer, oldest_pending timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select count(*) filter (where scan_status in ('pending', 'not_scanned'))::int, count(*) filter (where scan_status = 'scanning')::int,
         count(*) filter (where scan_status = 'clean')::int, count(*) filter (where scan_status = 'infected')::int,
         count(*) filter (where scan_status = 'scan_failed')::int, min(created_at) filter (where scan_status in ('pending', 'not_scanned'))
  from connect_attachments where is_executive() or connect_is_moderator() $$;


--
-- Name: connect_set_lock(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_set_lock(p_conversation uuid, p_locked boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not connect_is_moderator() then raise exception 'Only moderators can lock a discussion'; end if;
  update connect_conversations set locked = p_locked, locked_by = case when p_locked then auth.uid() end, locked_at = case when p_locked then now() end
   where id = p_conversation and kind = 'cohort';
  if not found then raise exception 'Only cohort discussions can be locked'; end if;
end $$;


--
-- Name: connect_start_direct(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_start_direct(p_facilitator uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare me uuid := my_participant_id(); cid uuid;
begin
  if app_role() is distinct from 'participant' or me is null then raise exception 'Only learners can start a private conversation with a facilitator'; end if;
  if not exists (select 1 from profiles where id = p_facilitator and role = 'trainer' and status = 'active') or not connect_facilitator_assigned(me, p_facilitator) then
    raise exception 'You can only message a facilitator assigned to your cohort';
  end if;
  insert into connect_conversations(kind, learner_id, facilitator_id, started_by) values ('direct', me, p_facilitator, auth.uid())
  on conflict (learner_id, facilitator_id) where kind = 'direct' do nothing;
  select id into cid from connect_conversations where kind = 'direct' and learner_id = me and facilitator_id = p_facilitator;
  return cid;
end $$;


--
-- Name: connect_start_direct_with_learner(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_start_direct_with_learner(p_learner uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid;
begin
  if app_role() is distinct from 'trainer' then raise exception 'Only facilitators can start a conversation with a learner'; end if;
  if not exists (select 1 from participants pa join profiles p on p.id = pa.profile_id where pa.id = p_learner and p.status = 'active')
     or not connect_facilitator_assigned(p_learner, auth.uid()) then
    raise exception 'You can only message learners in a cohort you are assigned to';
  end if;
  insert into connect_conversations(kind, learner_id, facilitator_id, started_by) values ('direct', p_learner, auth.uid(), auth.uid())
  on conflict (learner_id, facilitator_id) where kind = 'direct' do nothing;
  select id into cid from connect_conversations where kind = 'direct' and learner_id = p_learner and facilitator_id = auth.uid();
  return cid;
end $$;


--
-- Name: connect_start_safeguarding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_start_safeguarding() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare me uuid := my_participant_id(); cid uuid;
begin
  if app_role() is distinct from 'participant' or me is null then raise exception 'Only learners can start a conversation with the safeguarding team'; end if;
  if sg_acting_officer() is null then
    raise exception 'The safeguarding team has not been set up yet. Please speak to your facilitator or contact DIRA Foundation directly';
  end if;
  insert into connect_conversations(kind, learner_id, started_by) values ('safeguarding', me, auth.uid())
  on conflict (learner_id) where kind = 'safeguarding' do nothing;
  select id into cid from connect_conversations where kind = 'safeguarding' and learner_id = me;
  return cid;
end $$;


--
-- Name: connect_thread_messages(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_thread_messages(p_conversation uuid, p_before timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, sender_id uuid, sender_name text, sender_role text, body text, created_at timestamp with time zone, hidden boolean, mine boolean, attachments jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare learner_profile uuid; k text;
begin
  if not connect_can_see(p_conversation) then return; end if;
  select c.kind, pa.profile_id into k, learner_profile from connect_conversations c left join participants pa on pa.id = c.learner_id where c.id = p_conversation;
  return query
    select m.id, m.sender_id,
           case when pr.role = 'trainer' or (k = 'safeguarding' and m.sender_id is distinct from learner_profile) then btrim(pr.first_name || ' ' || pr.last_name)
                else btrim(pr.first_name || ' ' || left(coalesce(pr.last_name, ''), 1) || '.') end,
           case when k = 'safeguarding' and m.sender_id is distinct from learner_profile then 'Safeguarding team'
                when pr.role = 'trainer' then 'Facilitator' else 'Learner' end,
           m.body, m.created_at, (m.hidden_at is not null), (m.sender_id = auth.uid()),
           case when m.hidden_at is not null then '[]'::jsonb else coalesce((
             select jsonb_agg(jsonb_build_object('id', a.id, 'name', a.file_name, 'path', a.storage_path, 'mime', a.mime_type, 'size', a.size_bytes,
                    'scan', case when a.scan_status = 'not_scanned' then 'pending' else a.scan_status end) order by a.created_at)
             from connect_attachments a where a.message_id = m.id and a.scan_status <> 'infected'), '[]'::jsonb) end
    from connect_messages m join profiles pr on pr.id = m.sender_id
    where m.conversation_id = p_conversation and (p_before is null or m.created_at < p_before)
    order by m.created_at desc, m.id desc limit least(greatest(p_limit, 1), 100);
end $$;


--
-- Name: connect_threads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_threads() RETURNS TABLE(conversation_id uuid, kind text, title text, subtitle text, last_message_at timestamp with time zone, unread bigint, locked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.kind,
         case c.kind
           when 'cohort' then (select name from cohorts where id = c.cohort_id)
           when 'safeguarding' then case when c.learner_id = my_participant_id() then 'Safeguarding team'
                                     else (select btrim(first_name || ' ' || last_name) from profiles where id = (select profile_id from participants where id = c.learner_id)) end
           else case when c.facilitator_id = auth.uid() then (select btrim(first_name || ' ' || last_name) from profiles where id = (select profile_id from participants where id = c.learner_id))
                     else (select btrim(first_name || ' ' || last_name) from profiles where id = c.facilitator_id) end end,
         case c.kind when 'cohort' then 'Cohort discussion' when 'safeguarding' then 'Safeguarding (confidential)' else 'Private conversation' end,
         c.last_message_at,
         (select count(*) from connect_messages m where m.conversation_id = c.id and m.sender_id <> auth.uid() and m.hidden_at is null
            and m.created_at > coalesce((select r.last_read_at from connect_reads r where r.conversation_id = c.id and r.profile_id = auth.uid()), '-infinity'::timestamptz)),
         c.locked
  from connect_conversations c where connect_can_see(c.id)
  order by c.last_message_at desc nulls last, c.created_at desc $$;


--
-- Name: connect_unmute(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.connect_unmute(p_profile uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
