-- Name: email_report(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.email_report(p_from date, p_to date) RETURNS TABLE(status public.email_status, total bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.status, count(*) from email_outbox o where is_staff() and o.created_at >= p_from and o.created_at < p_to + 1 group by o.status $$;


--
-- Name: enforce_cohort_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_cohort_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cap int; cur int; arch boolean;
begin
  select capacity, archived into cap, arch from cohorts where id = new.cohort_id for update;
  if arch then raise exception 'This cohort is archived'; end if;
  select count(*) into cur from cohort_enrolments where cohort_id = new.cohort_id;
  if cur >= cap then raise exception 'Cohort is at capacity (%)', cap; end if;
  return new;
end $$;


--
-- Name: enforce_single_active_cohort(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_single_active_cohort() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if exists (select 1 from cohort_enrolments e join cohorts c on c.id = e.cohort_id
             where e.participant_id = new.participant_id and e.cohort_id <> new.cohort_id and not c.archived) then
    raise exception 'This participant is already enrolled in another active cohort';
  end if;
  return new;
end $$;


--
-- Name: enqueue_bulk_email(text, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_bulk_email(p_template text, p_audience text, p_cohort uuid, p_when timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; vars jsonb; label text;
begin
  if not is_staff() then raise exception 'Only programme management can send email'; end if;
  if p_when is not null and p_when < now() - interval '5 minutes' then raise exception 'The scheduled time is in the past'; end if;
  if p_audience not in ('cohort', 'all_participants', 'all_staff') then raise exception 'Unknown audience'; end if;
  if p_audience = 'cohort' and p_cohort is null then raise exception 'Choose a cohort'; end if;
  if not exists (select 1 from email_templates where key = p_template and is_active) then raise exception 'Template not found or switched off'; end if;
  label := 'bulk:' || p_template || ':' || to_char(now(), 'YYYY-MM-DD HH24:MI');
  for r in
    select distinct pr.id as uid, c.name as cohort_name, g.name as programme_name
    from profiles pr
    left join participants pa on pa.profile_id = pr.id
    left join cohort_enrolments e on e.participant_id = pa.id and (p_audience <> 'cohort' or e.cohort_id = p_cohort)
    left join cohorts c on c.id = e.cohort_id
    left join programmes g on g.id = c.programme_id
    where pr.status = 'active' and not pr.email_opt_out
      and ((p_audience = 'cohort' and e.cohort_id = p_cohort and pa.status <> 'withdrawn')
        or (p_audience = 'all_participants' and pr.role = 'participant' and pa.status <> 'withdrawn')
        or (p_audience = 'all_staff' and pr.role in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator', 'trainer', 'me_officer', 'mentor')))
  loop
    n := n + 1;
    if n > 500 then raise exception 'An audience is limited to 500 people per send'; end if;
    vars := jsonb_build_object('cohort_name', coalesce(r.cohort_name, ''), 'programme_name', coalesce(r.programme_name, ''));
    perform _enqueue_email(r.uid, p_template, vars, p_when, label, auth.uid());
  end loop;
  return n;
end $$;


--
-- Name: file_is_downloadable(text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_is_downloadable(p_bucket text, p_name text, p_updated_at timestamp with time zone, p_owner uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select not scanned_bucket(p_bucket)
      or exists (select 1 from storage_file_scans s where s.bucket_id = p_bucket and s.object_name = p_name
                 and s.status = 'clean' and s.object_updated_at = p_updated_at)
      or (p_owner is not null and p_owner = auth.uid()
          and not exists (select 1 from storage_file_scans s where s.bucket_id = p_bucket and s.object_name = p_name
                          and s.status = 'infected' and s.object_updated_at = p_updated_at)) $$;


--
-- Name: file_scan_queue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.file_scan_queue() RETURNS TABLE(bucket_id text, waiting integer, clean integer, infected integer, scan_failed integer, oldest_waiting timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select o.bucket_id,
         count(*) filter (where s.status is null or s.object_updated_at <> o.updated_at or s.status in ('pending', 'scanning'))::int,
         count(*) filter (where s.status = 'clean' and s.object_updated_at = o.updated_at)::int,
         count(*) filter (where s.status = 'infected' and s.object_updated_at = o.updated_at)::int,
         count(*) filter (where s.status = 'scan_failed' and s.object_updated_at = o.updated_at)::int,
         min(o.updated_at) filter (where s.status is null or s.object_updated_at <> o.updated_at or s.status in ('pending', 'scanning'))
  from storage.objects o left join storage_file_scans s on s.bucket_id = o.bucket_id and s.object_name = o.name
  where scanned_bucket(o.bucket_id) and (is_staff() or is_executive())
  group by o.bucket_id $$;


