-- Name: forbid_topic_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_topic_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin raise exception 'Topic proposals are never deleted. Reject a topic instead'; end $$;


--
-- Name: forbid_topic_event_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.forbid_topic_event_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin raise exception 'The approval history cannot be changed'; end $$;


--
-- Name: guard_account_status_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_account_status_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'Account status history cannot be deleted'; end if;
  if not is_trusted_session()
     or new.profile_id <> old.profile_id or new.old_status <> old.old_status or new.new_status <> old.new_status
     or new.reason <> old.reason or new.changed_by is distinct from old.changed_by or new.created_at <> old.created_at then
    raise exception 'Account status history cannot be changed';
  end if;
  return new;
end $$;


--
-- Name: guard_application_min_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_application_min_age() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare dob date := dob_from_form(new.form_data);
begin
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.status is distinct from 'submitted') and not is_trusted_session() then
    if dob is null then raise exception 'Enter your date of birth before submitting your application'; end if;
  end if;
  if new.status in ('submitted', 'accepted') and (tg_op = 'INSERT' or old.status is distinct from new.status)
     and dob is not null and dob > (current_date - interval '18 years')::date then
    raise exception 'DIRA LEARN is for people aged 18 to 25. Applications from people under 18 cannot be accepted';
  end if;
  return new;
end $$;


--
-- Name: guard_application_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_application_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status = 'submitted' and new.submitted_at is null then new.submitted_at := now(); end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    if auth.uid() is null or current_setting('dira.application_transition', true) = 'on' then
      return new;
    end if;
    if auth.uid() = old.applicant_id and old.status = 'draft' and new.status = 'submitted' then
      new.submitted_at := coalesce(new.submitted_at, now());
      return new;
    end if;
    raise exception 'Application status can only be changed through the review workflow';
  end if;
  return new;
end $$;


--
-- Name: guard_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(auth.uid(), new.created_by);
    return new;
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions s where s.assignment_id = old.id) then
      raise exception 'This assignment already has submissions and cannot be deleted';
    end if;
    return old;
  end if;
  -- UPDATE: cohort and marking scale are locked once work has been handed in
  if exists (select 1 from submissions s where s.assignment_id = old.id)
     and (new.cohort_id <> old.cohort_id or new.max_score is distinct from old.max_score or new.track_id is distinct from old.track_id) then
    raise exception 'Cohort, track and maximum score cannot change once submissions exist';
  end if;
  new.created_by := old.created_by;
  return new;
end $$;


--
-- Name: guard_assignment_component(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_assignment_component() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.component is distinct from old.component
     and exists (select 1 from submissions s where s.assignment_id = old.id) then
    raise exception 'The assessment component cannot change once submissions exist';
  end if;
  return new;
end $$;


--
-- Name: guard_assignment_recipient(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_assignment_recipient() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare a assignments;
begin
  if tg_op = 'INSERT' then
    select * into a from assignments where id = new.assignment_id;
    if not found then raise exception 'Assignment not found'; end if;
    if not exists (select 1 from cohort_enrolments e where e.participant_id = new.participant_id and e.cohort_id = a.cohort_id
                   and (a.track_id is null or e.track_id = a.track_id)) then
      raise exception 'That learner is not enrolled for this assignment';
    end if;
    new.created_by := coalesce(new.created_by, auth.uid());
    return new;
  end if;
  if tg_op = 'DELETE' then
    if exists (select 1 from submissions s where s.assignment_id = old.assignment_id and s.participant_id = old.participant_id)
       and exists (select 1 from assignments a2 where a2.id = old.assignment_id) then
      raise exception 'This learner has already submitted, so the assignment cannot be taken away';
    end if;
    return old;
  end if;
  raise exception 'Recipients cannot be edited; add or remove them';
end $$;


--
-- Name: guard_brief_publisher(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_brief_publisher() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r role_code;
begin
  select role into r from profiles where id = new.profile_id;
  if r is null or r not in ('programme_director', 'programme_coordinator', 'trainer') then
    raise exception 'Only programme staff and facilitators can be authorised to publish briefs (executives already can)';
  end if;
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  return new;
end $$;


--
-- Name: guard_certificate_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_certificate_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if coalesce(current_setting('app.certificate_fn', true), '') <> '1' then
    raise exception 'Certificates are issued and revoked only through issue_certificate and revoke_certificate';
  end if;
  return coalesce(new, old);
end $$;


--
-- Name: guard_cohort_access_times(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_cohort_access_times() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if is_trusted_session() then return new; end if;
  if (tg_op = 'INSERT' and (new.access_opens_at is not null or new.access_closes_at is not null))
     or (tg_op = 'UPDATE' and (new.access_opens_at, new.access_closes_at) is distinct from (old.access_opens_at, old.access_closes_at)) then
    if not can_manage_learner_access() then
      raise exception 'Only a super administrator, Founder, Co-Founder or programme director can set a cohort''s access times';
    end if;
  end if;
  return new;
end $$;


--
-- Name: guard_cohort_capacity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_cohort_capacity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cur int;
begin
  select count(*) into cur from cohort_enrolments where cohort_id = new.id;
  if new.capacity < cur then raise exception 'Capacity cannot be lower than the % participants already enrolled', cur; end if;
  return new;
end $$;


--
-- Name: guard_connect_attachment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connect_attachment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare m connect_messages; obj storage.objects; real_size bigint; real_mime text;
begin
  if is_trusted_session() then return new; end if;
  select * into m from connect_messages where id = new.message_id;
  if not found or m.sender_id <> auth.uid() or m.conversation_id <> new.conversation_id or m.hidden_at is not null or m.created_at < now() - interval '15 minutes' then
    raise exception 'Attach files only to a message you have just sent';
  end if;
  if new.storage_path not like new.conversation_id::text || '/' || auth.uid()::text || '/%' then raise exception 'The file is not in this conversation''s folder'; end if;
  select * into obj from storage.objects where bucket_id = 'connect-attachments' and name = new.storage_path;
  if not found then raise exception 'Upload the file before attaching it'; end if;
  real_size := coalesce((obj.metadata ->> 'size')::bigint, new.size_bytes);
  real_mime := coalesce(obj.metadata ->> 'mimetype', new.mime_type);
  if not connect_allowed_mime(real_mime) then raise exception 'Only PDF, Word, Excel, PowerPoint, JPG and PNG files can be attached'; end if;
  if real_size > 10485760 then raise exception 'Files can be at most 10 MB'; end if;
  if (select count(*) from connect_attachments where message_id = new.message_id) >= 3 then raise exception 'At most 3 files per message'; end if;
  new.size_bytes := real_size; new.mime_type := real_mime;
  new.file_name := left(regexp_replace(btrim(new.file_name), '[\\/\x00-\x1f<>:"|?*]', '_', 'g'), 200);
  new.uploaded_by := auth.uid(); new.scan_status := 'not_scanned'; new.created_at := now();
  return new;
end $$;


--
-- Name: guard_connect_attachment_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connect_attachment_scan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not is_trusted_session() then
    new.scan_status := 'pending'; new.scan_attempts := 0; new.scan_claimed_at := null; new.scanned_at := null; new.scan_engine := null; new.scan_detail := null;
  end if;
  return new;
end $$;


--
-- Name: guard_connect_message(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connect_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.body := btrim(new.body);
  if not is_trusted_session() and new.sender_id is distinct from auth.uid() then
    raise exception 'You can only send messages as yourself';
  end if;
  new.sender_id := coalesce(auth.uid(), new.sender_id);
  new.hidden_at := null; new.hidden_by := null; new.hide_reason := null;
  if not is_trusted_session() and (select count(*) from connect_messages m where m.sender_id = new.sender_id and m.created_at > now() - interval '1 minute') >= 15 then
    raise exception 'You are sending messages too quickly. Please wait a moment';
  end if;
  return new;
end $$;


--
-- Name: guard_connect_oversight(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connect_oversight() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r role_code;
begin
  select role into r from profiles where id = new.profile_id;
  if r is null or r not in ('super_admin', 'founder', 'co_founder', 'programme_director', 'programme_coordinator') then
    raise exception 'Oversight can only be granted to executives and programme staff';
  end if;
  if not is_trusted_session() and new.profile_id = auth.uid() then
    raise exception 'You cannot grant oversight to yourself. Another executive must approve it';
  end if;
  new.granted_by := coalesce(auth.uid(), new.granted_by);
  new.granted_at := now();
  return new;
end $$;


--
-- Name: guard_connect_retention_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_connect_retention_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now(); return new; end $$;


--
-- Name: guard_course(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  if tg_op = 'INSERT' then
    new.created_by := coalesce(auth.uid(), new.created_by);
    new.status := 'draft';   -- every course starts as a draft; publishing is a separate step once it has lessons
  elsif app_role() = 'trainer' then
    if new.status is distinct from old.status then raise exception 'Only programme management can publish or archive a course'; end if;
    if new.programme_id is distinct from old.programme_id or new.cohort_id is distinct from old.cohort_id or new.track_id is distinct from old.track_id then
      raise exception 'Only programme management can move a course to another programme, track or cohort';
    end if;
  end if;
  if new.track_id is not null and not exists (select 1 from tracks where id = new.track_id and programme_id = new.programme_id) then raise exception 'The track belongs to a different programme'; end if;
  if new.cohort_id is not null and not exists (select 1 from cohorts where id = new.cohort_id and programme_id = new.programme_id) then raise exception 'The cohort belongs to a different programme'; end if;
  if new.status = 'published' and (tg_op = 'INSERT' or old.status <> 'published') and not exists (select 1 from course_modules m join course_lessons l on l.module_id = m.id where m.course_id = new.id) and tg_op = 'UPDATE' then
    raise exception 'Add at least one lesson before publishing';
  end if;
  return new;
end $$;


--
-- Name: guard_course_enrolment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_enrolment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare c courses; p participants; pu uuid;
begin
  select * into c from courses where id = new.course_id;
  if c.status = 'archived' then raise exception 'An archived course cannot take new enrolments'; end if;
  select * into p from participants where id = new.participant_id;
  if p.status = 'withdrawn' then raise exception 'A withdrawn participant cannot be enrolled'; end if;
  if c.cohort_id is not null and not exists (select 1 from cohort_enrolments where cohort_id = c.cohort_id and participant_id = new.participant_id) then
    raise exception 'This course is for one cohort and the participant is not enrolled in it';
  end if;
  if c.track_id is not null and not exists (select 1 from cohort_enrolments e join cohorts k on k.id = e.cohort_id where e.participant_id = new.participant_id and e.track_id = c.track_id and k.programme_id = c.programme_id) then
    raise exception 'This course is for one track and the participant has not chosen it';
  end if;
  new.enrolled_by := coalesce(auth.uid(), new.enrolled_by);
  select profile_id into pu from participants where id = new.participant_id;
  insert into notifications(user_id, kind, title, body) values (pu, 'course', 'You were enrolled in a course', c.title);
  return new;
end $$;


--
-- Name: guard_course_lesson(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_lesson() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare cid uuid;
begin
  cid := course_of_module(new.module_id);
  if new.storage_path is not null and new.storage_path not like cid::text || '/%' then raise exception 'Lesson files must be stored in the course folder'; end if;
  return new;
end $$;


--
-- Name: guard_course_trainer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_course_trainer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from profiles where id = new.trainer_id and role = 'trainer' and status = 'active') then raise exception 'Only an active trainer account can be assigned to a course'; end if;
  return new;
end $$;


--
-- Name: guard_curriculum_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_curriculum_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare content_changed boolean;
begin
  if is_trusted_session() then return new; end if;                       -- service role / migrations
  if tg_op = 'INSERT' then
    if new.is_approved and coalesce(app_role() not in ('super_admin', 'founder', 'co_founder', 'programme_director'), true) then
      raise exception 'Only a super administrator or programme director can approve curriculum content';
    end if;
    return new;
  end if;
  if new.is_approved is distinct from old.is_approved then
    if coalesce(app_role() not in ('super_admin', 'founder', 'co_founder', 'programme_director'), true) then
      raise exception 'Only a super administrator or programme director can approve curriculum content';
    end if;
  end if;
  content_changed := (new.title, new.description, new.duration_minutes, new.objectives, new.topics, new.activities, new.expected_output, new.assessment_notes, new.week_no, new.session_no, new.track_id)
                     is distinct from
                     (old.title, old.description, old.duration_minutes, old.objectives, old.topics, old.activities, old.expected_output, old.assessment_notes, old.week_no, old.session_no, old.track_id);
  if content_changed and old.is_approved and new.is_approved is not distinct from old.is_approved then
    new.is_approved := false;                                          -- needs re-approval
  end if;
  return new;
end $$;


--
-- Name: guard_daily_brief(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_daily_brief() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    if not is_trusted_session() then
      if not can_publish_briefs() then raise exception 'You are not authorised to publish daily briefs'; end if;
      if old.status <> 'draft' then raise exception 'Only drafts can be deleted. Withdraw a published brief instead'; end if;
    end if;
    return old;
  end if;

  if not is_trusted_session() then
    if not can_publish_briefs() then raise exception 'You are not authorised to publish daily briefs'; end if;
    if app_role() = 'trainer' then
      if new.cohort_id is null or new.cohort_id not in (select my_trainer_cohorts()) then
        raise exception 'Facilitators can write briefs only for their own cohorts';
      end if;
      if tg_op = 'UPDATE' and (old.cohort_id is null or old.cohort_id not in (select my_trainer_cohorts())) then
        raise exception 'Facilitators can edit briefs only for their own cohorts';
      end if;
    end if;
    if new.status = 'scheduled' and (tg_op = 'INSERT' or old.status is distinct from 'scheduled' or old.publish_at is distinct from new.publish_at)
       and (new.publish_at is null or new.publish_at <= now()) then
      raise exception 'Choose a future time to schedule publication';
    end if;
  end if;

  if tg_op = 'INSERT' then new.created_by := coalesce(auth.uid(), new.created_by); end if;
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  new.updated_at := now();
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then new.published_at := now(); end if;
  if new.status = 'draft' then new.published_at := null; end if;
  if new.status <> 'scheduled' and new.status <> 'published' and new.status <> 'withdrawn' then new.publish_at := null; end if;
  return new;
end $$;


--
-- Name: guard_email_template(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_email_template() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now();
  if tg_op = 'UPDATE' and (new.key is distinct from old.key or new.is_system is distinct from old.is_system) then raise exception 'A template key cannot be changed'; end if;
  return new;
end $$;


--
-- Name: guard_graduation_rule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_graduation_rule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.min_overall_percent is not null then raise exception 'An overall-percent rule is not supported until assessment weights are approved'; end if;
  if new.min_sessions_attended is not null and new.min_sessions_attended < 1 then raise exception 'Minimum sessions must be at least 1'; end if;
  if tg_op = 'UPDATE' and old.is_approved and (
       new.min_sessions_attended is distinct from old.min_sessions_attended or new.require_core_sessions is distinct from old.require_core_sessions
       or new.require_final_project is distinct from old.require_final_project or new.require_reflection is distinct from old.require_reflection) then
    new.is_approved := false;
  end if;
  if new.is_approved and (tg_op = 'INSERT' or not old.is_approved) then new.approved_by := auth.uid(); new.approved_at := now(); end if;
  if not new.is_approved then new.approved_by := null; new.approved_at := null; end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: guard_learner_feedback(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_learner_feedback() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare learner_profile uuid;
begin
  if not is_trusted_session() then
    if not can_give_learner_feedback(new.participant_id, new.cohort_id) then
      raise exception 'Only the learner''s facilitators and programme staff can give feedback';
    end if;
    new.author_id := auth.uid();
  end if;
  new.body := btrim(new.body);
  new.created_at := now();
  if new.shared_with_learner then
    select profile_id into learner_profile from participants where id = new.participant_id;
    insert into notifications(user_id, kind, title, body) values (learner_profile, 'feedback', 'New feedback on your progress', 'Open Performance in DIRA LEARN to read it.');
  end if;
  return new;
end $$;


--
-- Name: guard_lesson_plan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_lesson_plan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  if is_trusted_session() then return new; end if;                 -- migrations, seed and service role
  new.updated_by := auth.uid();
  if tg_op = 'INSERT' then
    if new.status = 'approved' then
      if not can_approve_lesson_plans() then raise exception 'Only a super administrator, founder, co-founder or programme director can approve a lesson plan'; end if;
      new.approved_by := auth.uid(); new.approved_at := now();
    else
      new.approved_by := null; new.approved_at := null;
    end if;
    return new;
  end if;
  if new.session_id is distinct from old.session_id then raise exception 'A lesson plan cannot be moved to another session'; end if;
  if new.status is distinct from old.status then
    if new.status = 'approved' then
      if not can_approve_lesson_plans() then raise exception 'Only a super administrator, founder, co-founder or programme director can approve a lesson plan'; end if;
      new.approved_by := auth.uid(); new.approved_at := now();
    else
      new.approved_by := null; new.approved_at := null;             -- back to draft: allowed for anyone who may edit
    end if;
  elsif old.status = 'approved' and (new.content, new.version) is distinct from (old.content, old.version) then
    new.status := 'draft'; new.approved_by := null; new.approved_at := null;   -- edited after approval: needs approval again
  else
    new.approved_by := old.approved_by; new.approved_at := old.approved_at;
  end if;
  return new;
end $$;


--
-- Name: guard_me_record(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_me_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare ind_prog uuid; coh_prog uuid;
begin
  new.recorded_by := coalesce(auth.uid(), new.recorded_by);
  if new.cohort_id is not null then
    select programme_id into ind_prog from me_indicators where id = new.indicator_id;
    select programme_id into coh_prog from cohorts where id = new.cohort_id;
    if ind_prog is not null and coh_prog is distinct from ind_prog then
      raise exception 'The cohort does not belong to the indicator''s programme';
    end if;
  end if;
  return new;
end $$;


--
-- Name: guard_mentorship_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_mentorship_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from profiles where id = new.mentor_id and role = 'mentor' and status = 'active') then
    raise exception 'The mentor must be an active account with the mentor role';
  end if;
  if exists (select 1 from participants where id = new.participant_id and status = 'withdrawn') then
