  end if;
  return new;
end $$;


--
-- Name: guard_mentorship_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_mentorship_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.held_on > current_date then raise exception 'A mentoring session cannot be dated in the future'; end if;
  if jsonb_typeof(new.action_points) is distinct from 'array' then raise exception 'Action points must be a list'; end if;
  if jsonb_array_length(new.action_points) > 20 then raise exception 'At most 20 action points per session'; end if;
  return new;
end $$;


--
-- Name: guard_notification_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_notification_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.user_id is distinct from old.user_id or new.kind is distinct from old.kind or new.title is distinct from old.title
     or new.body is distinct from old.body or new.created_at is distinct from old.created_at then
    raise exception 'Only the read time of a notification can be changed';
  end if;
  return new;
end $$;


--
-- Name: guard_participant_min_age(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_participant_min_age() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if new.date_of_birth is not null and (tg_op = 'INSERT' or new.date_of_birth is distinct from old.date_of_birth)
     and new.date_of_birth > (current_date - interval '18 years')::date then
    raise exception 'DIRA LEARN participants must be at least 18 years old';
  end if;
  return new;
end $$;


--
-- Name: guard_performance_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_performance_settings() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin new.updated_by := coalesce(auth.uid(), new.updated_by); new.updated_at := now(); return new; end $$;


--
-- Name: guard_profile_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare has_participant boolean; remaining int;
begin
  if is_trusted_session() then return new; end if;
  if new.role is distinct from old.role or new.status is distinct from old.status then
    if auth.uid() = old.id then
      raise exception 'You cannot change your own role or status';
    end if;
  end if;
  if new.role is distinct from old.role then
    select exists (select 1 from participants where profile_id = new.id) into has_participant;
    if new.role = 'participant' and not has_participant then
      raise exception 'A participant account is created by converting an accepted application';
    end if;
    if old.role = 'participant' and has_participant then
      raise exception 'A participant cannot be given another role. Mark the participant as withdrawn instead';
    end if;
  end if;
  if old.role = 'super_admin' and old.status = 'active' and (new.role <> 'super_admin' or new.status <> 'active') then
    select count(*) into remaining from profiles where role = 'super_admin' and status = 'active' and id <> old.id;
    if remaining = 0 then raise exception 'There must always be at least one active super administrator'; end if;
  end if;
  return new;
end $$;


--
-- Name: guard_profile_privileged(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_privileged() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if is_trusted_session() then return new; end if;
  if current_setting('dira.application_decision', true) = 'on'
     and old.role = 'applicant' and new.role = 'participant'
     and new.status is not distinct from old.status
     and new.organization_id is not distinct from old.organization_id then
    return new;
  end if;
  if (new.role is distinct from old.role or new.status is distinct from old.status or new.organization_id is distinct from old.organization_id)
     and not is_admin() then
    raise exception 'Only a super administrator can change role, status or organisation';
  end if;
  return new;
end $$;


--
-- Name: guard_profile_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status is distinct from old.status and not is_trusted_session()
     and coalesce(current_setting('dira.account_status_change', true), '') <> 'on' then
    raise exception 'Account status is changed only with Deactivate or Reactivate on the Users page (a reason is required)';
  end if;
  return new;
end $$;


--
-- Name: guard_programme_timezone(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_programme_timezone() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if not exists (select 1 from pg_timezone_names where name = new.timezone) then
    raise exception 'Unknown time zone: %', new.timezone;
  end if;
  return new;
end $$;


--
-- Name: guard_project(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_project() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if app_role() = 'participant' then
    if exists (select 1 from participants where id = my_participant_id() and status = 'withdrawn') then raise exception 'Withdrawn participants cannot change projects'; end if;
    if tg_op = 'INSERT' then
      new.feedback := null; new.status := 'in_progress';
    else
      if new.participant_id is distinct from old.participant_id or new.feedback is distinct from old.feedback then raise exception 'You cannot change feedback or ownership'; end if;
      if old.status in ('submitted', 'reviewed') then raise exception 'This project is locked until a trainer returns it'; end if;
      if new.status = 'needs_revision' then new.status := 'in_progress'; end if;  -- editing a returned project means working on it again
      if new.status not in ('in_progress', 'submitted') then raise exception 'You can only keep working or submit'; end if;
    end if;
  end if;
  return new;
end $$;


--
-- Name: guard_project_evidence(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_project_evidence() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare pstatus text; powner uuid;
begin
  if app_role() = 'participant' then
    select status, participant_id into pstatus, powner from participant_projects where id = new.project_id;
    if powner is distinct from my_participant_id() then raise exception 'Not your project'; end if;
    if pstatus not in ('in_progress', 'needs_revision') then raise exception 'Evidence cannot be added while the project is submitted or reviewed'; end if;
    if new.storage_path not like auth.uid()::text || '/%' then raise exception 'Evidence files must be stored in your own folder'; end if;
  end if;
  return new;
end $$;


--
-- Name: guard_safeguarding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_safeguarding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s safeguarding_settings;
begin
  select * into s from safeguarding_settings limit 1;
  if tg_op = 'INSERT' then
    new.reported_by := coalesce(auth.uid(), new.reported_by);
    new.created_at := now();
    new.status := 'open';
    new.acknowledged_at := null; new.acknowledged_by := null; new.resolved_at := null; new.overdue_alerted_at := null;
    new.ack_due_at := now() + case when new.urgency = 'urgent' then make_interval(mins => s.urgent_ack_minutes) else make_interval(hours => s.standard_ack_hours) end;
  else
    new.reported_by := old.reported_by; new.created_at := old.created_at; new.source := old.source; new.source_report_id := old.source_report_id;
    new.reported_message := old.reported_message; new.reported_sender := old.reported_sender;
    if not is_trusted_session() then new.ack_due_at := old.ack_due_at; end if;  -- only server-side corrections may move the target
    if old.status = 'open' and new.status <> 'open' and old.acknowledged_at is null then
      new.acknowledged_at := now(); new.acknowledged_by := auth.uid();
    else
      new.acknowledged_at := old.acknowledged_at; new.acknowledged_by := old.acknowledged_by;
    end if;
    if new.status in ('resolved', 'closed') and old.status not in ('resolved', 'closed') then new.resolved_at := now();
    elsif new.status not in ('resolved', 'closed') then new.resolved_at := null;
    else new.resolved_at := old.resolved_at; end if;
    if new.legal_hold and coalesce(btrim(new.legal_hold_reason), '') = '' then raise exception 'A legal hold needs a reason'; end if;
  end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: guard_safeguarding_action(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_safeguarding_action() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.actor_id := coalesce(auth.uid(), new.actor_id);
  new.created_at := now();
  return new;
end $$;


--
-- Name: guard_scheduled_curriculum(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_scheduled_curriculum() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if (new.week_no, new.session_no, new.track_id) is distinct from (old.week_no, old.session_no, old.track_id)
     and exists (select 1 from session_schedules where curriculum_session_id = old.id) then
    raise exception 'This session is already scheduled, so its week, number and track cannot change';
  end if;
  return new;
end $$;


--
-- Name: guard_session_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_session_schedule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  cs record; co record; tz text; day date; clash record;
begin
  if tg_op = 'UPDATE' and old.status = 'completed'
     and (new.starts_at <> old.starts_at or new.ends_at <> old.ends_at or new.cohort_id <> old.cohort_id or new.curriculum_session_id <> old.curriculum_session_id) then
    raise exception 'A completed session cannot be moved';
  end if;
  if new.status in ('cancelled', 'rescheduled') then return new; end if;

  select * into co from cohorts where id = new.cohort_id;
  select * into cs from curriculum_sessions where id = new.curriculum_session_id;
  if co.archived then raise exception 'This cohort is archived'; end if;
  if cs.programme_id <> co.programme_id then raise exception 'Session belongs to a different programme'; end if;

  select coalesce(trim(both '"' from value::text), 'Africa/Nairobi') into tz from system_settings where key = 'programme_timezone';
  day := (new.starts_at at time zone coalesce(tz, 'Africa/Nairobi'))::date;
  if day < co.start_date or day > co.end_date then
    raise exception 'Session date % is outside the cohort dates (% to %)', day, co.start_date, co.end_date;
  end if;
  if new.trainer_id is not null then
    if not exists (select 1 from trainer_assignments ta where ta.cohort_id = new.cohort_id and ta.trainer_id = new.trainer_id
                   and (ta.track_id is null or ta.track_id = cs.track_id)) then
      raise exception 'This trainer is not assigned to the cohort%', case when cs.track_id is not null then ' for this track' else '' end;
    end if;
    select s.id into clash from session_schedules s
      where s.trainer_id = new.trainer_id and s.status in ('scheduled', 'completed') and s.id is distinct from new.id
        and tstzrange(s.starts_at, s.ends_at) && tstzrange(new.starts_at, new.ends_at) limit 1;
    if found then raise exception 'The trainer already has a session at that time'; end if;
  end if;

  -- Within one cohort, sessions for DIFFERENT tracks may run in parallel; core sessions need the whole cohort.
  select s.id into clash from session_schedules s join curriculum_sessions o on o.id = s.curriculum_session_id
    where s.cohort_id = new.cohort_id and s.status in ('scheduled', 'completed') and s.id is distinct from new.id
      and tstzrange(s.starts_at, s.ends_at) && tstzrange(new.starts_at, new.ends_at)
      and not (cs.track_id is not null and o.track_id is not null and o.track_id <> cs.track_id) limit 1;
  if found then raise exception 'This cohort already has a session at that time'; end if;
  return new;
end $$;


--
-- Name: guard_setting(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_setting() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if tg_op = 'UPDATE' and old.is_approved and new.value is distinct from old.value then new.is_approved := false; end if;
  if new.is_approved and (tg_op = 'INSERT' or not old.is_approved) then new.approved_by := auth.uid(); new.approved_at := now(); end if;
  if not new.is_approved then new.approved_by := null; new.approved_at := null; end if;
  new.updated_at := now();
  return new;
end $$;


--
-- Name: guard_submission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_submission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  a record; owner uuid; last_attempt int; last_status submission_status; newer boolean;
begin
  select * into a from assignments where id = new.assignment_id;
  if not found then raise exception 'Assignment not found'; end if;

  if tg_op = 'INSERT' then
    if not exists (select 1 from cohort_enrolments e where e.participant_id = new.participant_id and e.cohort_id = a.cohort_id
                   and (a.track_id is null or e.track_id = a.track_id)) then
      raise exception 'You are not enrolled for this assignment';
    end if;
    if exists (select 1 from assignment_recipients r where r.assignment_id = a.id)
       and not exists (select 1 from assignment_recipients r where r.assignment_id = a.id and r.participant_id = new.participant_id) then
      raise exception 'This assignment was not assigned to you';
    end if;
    if coalesce(btrim(new.body), '') = '' and new.storage_path is null then
      raise exception 'Add your answer or attach a file';
    end if;
    if new.storage_path is not null then
      select profile_id into owner from participants where id = new.participant_id;
      if left(new.storage_path, 37) <> owner::text || '/' then raise exception 'Invalid file location'; end if;
    end if;

    select attempt, status into last_attempt, last_status from submissions
      where assignment_id = new.assignment_id and participant_id = new.participant_id order by attempt desc limit 1;
    if found then
      if not a.allow_resubmission then raise exception 'Resubmission is not allowed for this assignment'; end if;
      if last_status <> 'returned' then raise exception 'You can submit again only after your trainer returns your work'; end if;
      new.attempt := last_attempt + 1;
    else
      new.attempt := 1;
    end if;

    new.status := case when a.due_at is not null and now() > a.due_at then 'late' else 'submitted' end;
    new.submitted_at := now();
    new.feedback := null; new.score := null; new.graded_by := null;
    return new;
  end if;

  -- UPDATE (grading by a trainer or staff)
  if new.assignment_id <> old.assignment_id or new.participant_id <> old.participant_id or new.attempt <> old.attempt
     or new.body is distinct from old.body or new.storage_path is distinct from old.storage_path or new.submitted_at <> old.submitted_at then
    raise exception 'Submitted work cannot be changed';
  end if;
  if new.status is not distinct from old.status and new.score is not distinct from old.score and new.feedback is not distinct from old.feedback then
    return new;   -- nothing graded
  end if;

  select exists (select 1 from submissions s where s.assignment_id = new.assignment_id and s.participant_id = new.participant_id and s.attempt > new.attempt) into newer;
  if newer then raise exception 'Only the latest attempt can be graded'; end if;

  if new.status not in ('graded', 'returned') then raise exception 'Grade the work or return it for revision'; end if;
  if new.status = 'graded' then
    if a.max_score is null then
      if new.score is not null then raise exception 'This assignment has no marks; give feedback only'; end if;
    else
      if new.score is null then raise exception 'Enter a score'; end if;
      if new.score < 0 or new.score > a.max_score then raise exception 'Score must be between 0 and %', a.max_score; end if;
    end if;
  else  -- returned for revision
    if not a.allow_resubmission then raise exception 'This assignment does not allow resubmission'; end if;
    if coalesce(btrim(new.feedback), '') = '' then raise exception 'Say what needs to change before returning the work'; end if;
    if new.score is not null then raise exception 'A returned submission has no score yet'; end if;
  end if;
  new.graded_by := coalesce(auth.uid(), old.graded_by);
  return new;
end $$;


--
-- Name: guard_teaching_notes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_teaching_notes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at := now();
  if is_trusted_session() then return new; end if;
  new.updated_by := auth.uid();
  if tg_op = 'UPDATE' and new.session_id is distinct from old.session_id then raise exception 'Teaching notes cannot be moved to another session'; end if;
  if tg_op = 'INSERT' or new.content is distinct from old.content then
    update curriculum_lesson_plans set status = 'draft' where session_id = new.session_id and status = 'approved';
  end if;
  return new;
end $$;


--
-- Name: guard_topic_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_topic_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if (new.status is distinct from old.status or new.reviewed_by is distinct from old.reviewed_by
      or new.reviewed_at is distinct from old.reviewed_at or new.reviewer_comment is distinct from old.reviewer_comment)
     and not (current_setting('dira.topic_review', true) = 'on' or is_trusted_session()) then
    raise exception 'A topic can only be approved or rejected with the review action';
  end if;
  return new;
end $$;


--
-- Name: guard_trainer_assignment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_trainer_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not exists (select 1 from profiles where id = new.trainer_id and role = 'trainer' and status = 'active') then
    raise exception 'Only an active trainer account can be assigned to a cohort';
  end if;
  if new.track_id is not null and not exists (
      select 1 from tracks t join cohorts c on c.programme_id = t.programme_id where t.id = new.track_id and c.id = new.cohort_id) then
    raise exception 'Track does not belong to this cohort''s programme';
  end if;
  return new;
end $$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into profiles(id, role, status) values (new.id, 'applicant', 'active') on conflict (id) do nothing;
  return new;
end $$;


