--
-- Name: issue_certificate(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_certificate(p_participant uuid, p_cohort uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare prog uuid; r graduation_rules; c record; cid uuid; pstatus participant_status; pprofile uuid;
begin
  if coalesce(app_role() not in ('super_admin', 'founder', 'co_founder', 'programme_director'), true) then raise exception 'Only a super administrator or programme director can issue certificates'; end if;
  select programme_id into prog from cohorts where id = p_cohort;
  if prog is null then raise exception 'Cohort not found'; end if;
  if not exists (select 1 from cohort_enrolments where cohort_id = p_cohort and participant_id = p_participant) then raise exception 'The participant is not enrolled in this cohort'; end if;
  select status, profile_id into pstatus, pprofile from participants where id = p_participant;
  if pstatus = 'withdrawn' then raise exception 'A withdrawn participant cannot receive a certificate'; end if;
  select * into r from graduation_rules where programme_id = prog and is_approved;
  if not found then raise exception 'Graduation rules have not been approved by management'; end if;
  if exists (select 1 from certificates where participant_id = p_participant and cohort_id = p_cohort and not revoked) then raise exception 'This participant already has an active certificate for this cohort'; end if;

  select * into c from participant_completion(p_participant, p_cohort);
  if r.min_sessions_attended is not null and c.sessions_attended < r.min_sessions_attended then
    raise exception 'Attendance requirement not met (% of % sessions)', c.sessions_attended, r.min_sessions_attended; end if;
  if r.require_core_sessions and (c.core_total = 0 or c.core_attended < c.core_total) then raise exception 'Core sessions requirement not met'; end if;
  if r.require_final_project and not c.final_submitted then raise exception 'The final project has not been submitted'; end if;
  if r.require_reflection and not c.reflection_submitted then raise exception 'The reflection has not been submitted'; end if;

  perform set_config('app.certificate_fn', '1', true);
  insert into certificates(participant_id, cohort_id, issued_by, rules_id) values (p_participant, p_cohort, auth.uid(), r.id) returning id into cid;
  perform set_config('app.certificate_fn', '', true);
  update participants set status = 'graduated' where id = p_participant and status in ('enrolled', 'active', 'completed');
  insert into notifications(user_id, kind, title, body) values (pprofile, 'certificate', 'Your certificate is ready', 'Open Certificates to view or print it.');
  return cid;
end $$;


--
-- Name: learner_access_history(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_access_history(p_participant uuid) RETURNS TABLE(created_at timestamp with time zone, cohort_name text, action text, opens_at timestamp with time zone, closes_at timestamp with time zone, reason text, actor_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select ev.created_at, c.name, ev.action, ev.opens_at, ev.closes_at, ev.reason, btrim(coalesce(ap.first_name, '') || ' ' || coalesce(ap.last_name, ''))
  from learner_access_events ev join cohorts c on c.id = ev.cohort_id left join profiles ap on ap.id = ev.actor
  where ev.participant_id = p_participant and is_staff() order by ev.created_at desc $$;


--
-- Name: learner_access_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_access_state(p_participant uuid, p_cohort uuid) RETURNS public.learner_access_status
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  c cohorts; a learner_access; opens timestamptz; closes timestamptz;
begin
  if not coalesce(is_trusted_session() or is_staff() or p_participant = my_participant_id() or trainer_can_see_participant(p_participant), false) then return null; end if;
  select * into c from cohorts where id = p_cohort;
  if not found then return null; end if;
  if not exists (select 1 from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort) then return 'pending'; end if;
  if exists (select 1 from participants where id = p_participant and status = 'withdrawn') then return 'suspended'; end if;
  select * into a from learner_access where participant_id = p_participant and cohort_id = p_cohort;
  if found and a.suspended then return 'suspended'; end if;
  opens := coalesce(a.opens_at_override, c.access_opens_at);
  closes := coalesce(a.closes_at_override, c.access_closes_at);
  if opens is null then return 'pending'; end if;
  if now() < opens then return 'scheduled'; end if;
  if closes is not null and now() >= closes then return 'expired'; end if;
  return 'active';
end $$;


--
-- Name: learner_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_metrics(p_cohort uuid) RETURNS TABLE(participant_id uuid, participant_no text, display_name text, track_id uuid, track_name text, participant_status text, access_status text, attendance_records integer, attendance_rate numeric, sessions_attended integer, core_attended integer, core_total integer, assignments_expected integer, submitted integer, graded integer, returned integer, overdue integer, late integer, tasks_pct numeric, tasks_graded integer, tasks_total integer, final_pct numeric, final_graded integer, final_total integer, reflection_pct numeric, reflection_graded integer, reflection_total integer, overall numeric, provisional boolean, final_submitted boolean, reflection_submitted boolean, completion_met boolean, certified boolean, completion_status text, needs_support boolean, support_reasons text[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select m.* from _learner_metrics(p_cohort) m where can_view_learner_performance(m.participant_id, p_cohort) $$;


