--
-- Name: learner_performance_history(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.learner_performance_history(p_participant uuid, p_cohort uuid) RETURNS SETOF public.learner_progress_snapshots
    LANGUAGE sql STABLE SECURITY DEFINER
