    AS $$
  select * from learner_progress_snapshots s
  where s.participant_id = p_participant and s.cohort_id = p_cohort and can_view_learner_performance(p_participant, p_cohort)
  order by s.taken_on $$;


--
-- Name: lesson_plan_timing_problem(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_plan_timing_problem(p_session uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare dur int; segs jsonb; nsegs int; total int; bad int; notes_segs int;
begin
  select cs.duration_minutes, lp.content -> 'segments', jsonb_array_length(tn.content -> 'segments')
    into dur, segs, notes_segs
    from curriculum_sessions cs join curriculum_lesson_plans lp on lp.session_id = cs.id
    left join curriculum_teaching_notes tn on tn.session_id = cs.id
   where cs.id = p_session;
  if segs is null then return null; end if;                          -- no lesson plan: nothing to check
  select count(*) filter (where jsonb_typeof(e -> 'minutes') <> 'number' or (e ->> 'minutes')::numeric <> trunc((e ->> 'minutes')::numeric) or (e ->> 'minutes')::numeric < 1)
    into bad from jsonb_array_elements(segs) e;
  if bad > 0 then return 'every segment needs a whole number of minutes (at least 1)'; end if;
  select sum((e ->> 'minutes')::int), count(*) into total, nsegs from jsonb_array_elements(segs) e;
  if total <> dur then return format('the segments add up to %s minutes but the session is %s minutes', total, dur); end if;
  if notes_segs is not null and notes_segs <> nsegs then return format('the teaching notes have %s segments but the lesson plan has %s', notes_segs, nsegs); end if;
  return null;
end $$;


--
-- Name: load_curriculum_v13(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.load_curriculum_v13() RETURNS TABLE(item text, outcome text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  prog constant uuid := '00000000-0000-0000-0000-0000000000a1';
  t record; s record; tr record; cs record; n int; rec jsonb; obj text[]; act text[];
begin
  for t in select * from curriculum_v13_tracks order by code loop
    item := 'track ' || t.code;
    select * into tr from tracks where programme_id = prog and code = t.code;
    if not found then outcome := 'skipped: track not found'; return next; continue; end if;
    if tr.name = t.name and tr.focus is not distinct from t.focus then outcome := 'already current'; return next; continue; end if;
    insert into curriculum_v13_previous(kind, ref, data) values ('track', tr.id, jsonb_build_object('name', tr.name, 'focus', tr.focus)) on conflict do nothing;
    outcome := '';
    if tr.name = t.name then null;
    elsif tr.name = t.previous_name then update tracks set name = t.name where id = tr.id; outcome := 'renamed to ' || t.name;
    elsif tr.name <> t.name then outcome := 'name kept (edited since the seed: ' || tr.name || ')'; end if;
    if tr.focus is not distinct from t.focus then null;
    elsif tr.focus is not distinct from t.previous_focus then update tracks set focus = t.focus where id = tr.id; outcome := concat_ws('; ', nullif(outcome, ''), 'focus updated');
    elsif tr.focus is distinct from t.focus then outcome := concat_ws('; ', nullif(outcome, ''), 'focus kept (edited since the seed)'); end if;
    return next;
  end loop;

  for s in select * from curriculum_v13_sessions order by case when track_code = 'core' then 0 else 1 end, track_code, session_no loop
    item := case when s.track_code = 'core' then 'core' else s.track_code end || ' session ' || s.session_no;
    select c.* into cs from curriculum_sessions c left join tracks tk on tk.id = c.track_id
     where c.programme_id = prog and c.session_no = s.session_no
       and ((s.track_code = 'core' and c.track_id is null) or (s.track_code <> 'core' and tk.code = s.track_code));
    if not found then outcome := 'skipped: session not found'; return next; continue; end if;
    if cs.duration_minutes <> s.duration_minutes then
      outcome := format('skipped: the session is %s minutes but the V13 plan is %s (durations are never changed)', cs.duration_minutes, s.duration_minutes);
      return next; continue;
    end if;
    rec := s.session;
    obj := array(select jsonb_array_elements_text(rec -> 'objectives'));
    act := array(select jsonb_array_elements_text(rec -> 'activities'));
    if s.preserve_approved or cs.is_approved then
      outcome := 'approved session record kept unchanged';
    elsif (cs.title, cs.description, cs.objectives, cs.activities, cs.expected_output, cs.assessment_notes)
          is not distinct from (rec ->> 'title', rec ->> 'description', obj, act, rec ->> 'expected_output', rec ->> 'assessment_notes') then
      outcome := 'session record already current';
    elsif cs.title in (s.previous_title, rec ->> 'title') then
      insert into curriculum_v13_previous(kind, ref, data) values ('session', cs.id, jsonb_build_object(
        'title', cs.title, 'description', cs.description, 'objectives', to_jsonb(cs.objectives), 'activities', to_jsonb(cs.activities),
        'expected_output', cs.expected_output, 'assessment_notes', cs.assessment_notes, 'source', cs.source)) on conflict do nothing;
      update curriculum_sessions set title = rec ->> 'title', description = rec ->> 'description', objectives = obj, activities = act,
             expected_output = rec ->> 'expected_output', assessment_notes = rec ->> 'assessment_notes', source = 'curriculum_v13'
       where id = cs.id;
      outcome := 'session record updated';
    else
      outcome := 'session record kept (edited since the seed)';
    end if;
    insert into curriculum_lesson_plans(session_id, version, content) values (cs.id, 'V13', s.plan) on conflict (session_id) do nothing;
    get diagnostics n = row_count;
    if n = 1 then
      insert into curriculum_teaching_notes(session_id, content) values (cs.id, s.notes) on conflict (session_id) do nothing;
      outcome := outcome || '; lesson plan and teaching notes added (draft)';
    else
      outcome := outcome || '; lesson plan already present, not changed';
    end if;
    return next;
  end loop;
end $$;


--
-- Name: log_application_submitted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_application_submitted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.status = 'submitted' and (tg_op = 'INSERT' or old.status = 'draft') then
    insert into application_events(application_id, from_status, to_status, actor_id)
      values (new.id, case when tg_op = 'UPDATE' then 'draft'::application_status end, 'submitted', new.applicant_id);
  end if;
  return new;
end $$;


--
-- Name: log_daily_brief(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_daily_brief() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare act text;
begin
  if tg_op = 'INSERT' then act := 'created';
  elsif old.status is distinct from new.status then
    act := case new.status
      when 'published' then case when old.status = 'scheduled' and auth.uid() is null then 'published_on_schedule' else 'published' end
      when 'scheduled' then 'scheduled'
      when 'withdrawn' then 'withdrawn'
      else 'returned_to_draft' end;
  else act := 'edited';
  end if;
  insert into daily_brief_events(brief_id, action, title, brief_date, cohort_id, actor) values (new.id, act, new.title, new.brief_date, new.cohort_id, auth.uid());
  return new;
end $$;


--
-- Name: log_safeguarding_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_safeguarding_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare actor uuid := auth.uid();
begin
  if tg_op = 'INSERT' then
    insert into safeguarding_actions(record_id, action, to_status, note, actor_id) values (new.id, 'created', new.status, null, actor);
    -- urgent: the Lead AND the Deputy at once; otherwise the acting officer
    if new.urgency = 'urgent' then
      perform sg_notify(o, 'An URGENT safeguarding concern needs your attention now') from sg_officer_ids() o;
    else
      perform sg_notify(sg_acting_officer(), 'A safeguarding concern needs acknowledgement within the target time');
    end if;
    return new;
  end if;
  if new.status is distinct from old.status then
    insert into safeguarding_actions(record_id, action, from_status, to_status, actor_id)
    values (new.id, case when old.status = 'open' and old.acknowledged_at is null then 'acknowledged'
                         when new.status in ('resolved', 'closed') then 'resolved'
                         else 'status_changed' end, old.status, new.status, actor);
  end if;
  if new.responsible_officer is distinct from old.responsible_officer then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (new.id, 'assigned', null, actor);
  end if;
  if new.legal_hold is distinct from old.legal_hold then
    insert into safeguarding_actions(record_id, action, note, actor_id) values (new.id, case when new.legal_hold then 'legal_hold_on' else 'legal_hold_off' end, new.legal_hold_reason, actor);
  end if;
  return new;
end $$;


--
-- Name: mark_alumni(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_alumni(p_participant uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not is_staff() then raise exception 'Only programme staff can do this'; end if;
  if not exists (select 1 from participants where id = p_participant and status = 'graduated') then raise exception 'Only a graduated participant can become an alumnus'; end if;
  update participants set status = 'alumni' where id = p_participant;
  insert into alumni(participant_id) values (p_participant) on conflict (participant_id) do nothing;
end $$;


--
-- Name: mentor_has_mentee(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mentor_has_mentee(pid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select app_role() is not distinct from 'mentor'
     and exists (select 1 from mentorship_assignments m where m.mentor_id = auth.uid() and m.participant_id = pid) $$;


--
-- Name: my_learning_access(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_learning_access() RETURNS TABLE(cohort_id uuid, cohort_name text, status public.learner_access_status, opens_at timestamp with time zone, closes_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.cohort_id, c.name, learner_access_state(e.participant_id, e.cohort_id),
         coalesce(a.opens_at_override, c.access_opens_at), coalesce(a.closes_at_override, c.access_closes_at)
  from cohort_enrolments e
  join participants p on p.id = e.participant_id and p.profile_id = auth.uid()
  join profiles pr on pr.id = p.profile_id and pr.status = 'active'
  join cohorts c on c.id = e.cohort_id
  left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id $$;


--
-- Name: my_participant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_participant_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select pa.id from participants pa join profiles p on p.id = pa.profile_id
  where pa.profile_id = auth.uid() and p.status = 'active' $$;


--
-- Name: my_performance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_performance() RETURNS TABLE(cohort_id uuid, cohort_name text, metrics jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select e.cohort_id, co.name, to_jsonb(m)
  from cohort_enrolments e join cohorts co on co.id = e.cohort_id
  cross join lateral (select * from _learner_metrics(e.cohort_id) x where x.participant_id = e.participant_id) m
  where app_role() = 'participant' and e.participant_id = my_participant_id() and can_view_learner_performance(e.participant_id, e.cohort_id)
  order by co.start_date desc $$;


--
-- Name: my_trainer_cohorts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_trainer_cohorts() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select ta.cohort_id from trainer_assignments ta where ta.trainer_id = auth.uid() and app_role() = 'trainer' $$;


--
-- Name: next_participant_no(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_participant_no() RETURNS text
    LANGUAGE sql
    AS $$
  select 'DL-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('participant_seq')::text, 4, '0') $$;


--
-- Name: notification_to_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notification_to_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not email_automation_enabled() then return new; end if;
  if new.kind not in ('announcement', 'assignment', 'certificate', 'application', 'course') then return new; end if;
  if exists (select 1 from profiles where id = new.user_id and email_opt_out) then return new; end if;
  perform _enqueue_email(new.user_id, 'notification', jsonb_build_object('title', new.title, 'body', coalesce(new.body, '')), now(), 'event:' || new.kind, null);
  return new;
end $$;


--
-- Name: notify_access_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_access_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare uid uuid; cname text; tz text; ttl text; msg text; fmt constant text := 'FMDay DD Mon YYYY HH24:MI';
begin
  select pa.profile_id into uid from participants pa where pa.id = new.participant_id;
  select c.name, g.timezone into cname, tz from cohorts c join programmes g on g.id = c.programme_id where c.id = new.cohort_id;
  if uid is null or cname is null then return new; end if;
  if new.action = 'suspended' then
    ttl := 'Your learning access is paused'; msg := 'Your access to ' || cname || ' has been paused. Please contact the programme team.';
  elsif new.action = 'reinstated' then
    ttl := 'Your learning access is restored'; msg := 'Your access to ' || cname || ' is open again.';
  elsif new.action = 'override_cleared' then
    ttl := 'Your learning access dates changed'; msg := 'Your access to ' || cname || ' now follows the cohort dates.';
  else
    ttl := 'Your learning access dates changed';
    msg := 'Your access to ' || cname || ' has new dates.'
      || coalesce(' Opens: ' || to_char(new.opens_at at time zone tz, fmt) || '.', '')
      || coalesce(' Closes: ' || to_char(new.closes_at at time zone tz, fmt) || '.', '')
      || ' (Times are in ' || tz || '.)';
  end if;
  insert into notifications(user_id, kind, title, body) values (uid, 'access', ttl, msg);
  if email_automation_enabled() and not exists (select 1 from profiles where id = uid and email_opt_out) then
    perform _enqueue_email(uid, 'access_changed', jsonb_build_object('cohort_name', cname, 'change_title', ttl, 'change_body', msg), now(), 'event:access', null);
  end if;
  return new;
end $$;


--
-- Name: notify_application_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_application_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if current_setting('dira.application_decision', true) = 'on' then return new; end if;
  insert into notifications(user_id, kind, title, body) values (new.applicant_id, 'application', 'There is an update on your application', 'Open My application to read it.');
  return new;
end $$;


--
-- Name: notify_submission_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_submission_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  insert into notifications(user_id, kind, title, body)
  select p.profile_id, 'assignment', case when new.status = 'graded' then 'Your work was graded' else 'Your work was returned for revision' end,
         (select a.title from assignments a where a.id = new.assignment_id)
  from participants p where p.id = new.participant_id;
  return new;
end $$;


--
-- Name: participant_access_active(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.participant_access_active() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when app_role() = 'participant' then exists (
    select 1 from cohort_enrolments e join participants p on p.id = e.participant_id
    where p.profile_id = auth.uid() and learner_access_state(e.participant_id, e.cohort_id) = 'active')
  else true end $$;


--
-- Name: participant_access_expired(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.participant_access_expired() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select case when app_role() = 'participant' then exists (
    select 1 from cohort_enrolments e join participants p on p.id = e.participant_id
    where p.profile_id = auth.uid() and learner_access_state(e.participant_id, e.cohort_id) = 'expired')
  else false end $$;


--
-- Name: participant_can_view_course(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.participant_can_view_course(cid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists (select 1 from course_enrolments e join courses c on c.id = e.course_id
                 where e.course_id = cid and c.status = 'published' and e.participant_id = my_participant_id()) $$;


--
-- Name: participant_completion(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.participant_completion(p_participant uuid, p_cohort uuid) RETURNS TABLE(sessions_attended integer, core_attended integer, core_total integer, final_submitted boolean, reflection_submitted boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  with enrol as (select track_id from cohort_enrolments where participant_id = p_participant and cohort_id = p_cohort),
  sched as (
    select s.id, s.curriculum_session_id, cs.track_id from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id
    where s.cohort_id = p_cohort and s.status <> 'cancelled'),
  att as (
    select distinct sc.curriculum_session_id, (sc.track_id is null) as is_core
    from sched sc join attendance a on a.schedule_id = sc.id
    where a.participant_id = p_participant and a.status in ('present', 'late')
      and (sc.track_id is null or sc.track_id = (select track_id from enrol)))
  select (select count(*)::int from att),
         (select count(*) filter (where is_core)::int from att),
         (select count(distinct curriculum_session_id)::int from sched where track_id is null),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'final_project'),
         exists (select 1 from submissions sub join assignments asg on asg.id = sub.assignment_id
                 where sub.participant_id = p_participant and asg.cohort_id = p_cohort and asg.component = 'reflection') $$;


--
-- Name: performance_cohorts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.performance_cohorts() RETURNS TABLE(id uuid, name text, start_date date, end_date date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.id, c.name, c.start_date, c.end_date from cohorts c
  where is_staff()
     or (app_role() = 'trainer' and c.id in (select my_trainer_cohorts()))
     or (app_role() = 'mentor' and exists (select 1 from cohort_enrolments e join mentorship_assignments m on m.participant_id = e.participant_id
                                            where e.cohort_id = c.id and m.mentor_id = auth.uid()))
  order by c.start_date desc $$;


--
-- Name: publish_due_briefs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_due_briefs() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  update daily_briefs set status = 'published', published_at = now() where status = 'scheduled' and publish_at <= now();
  get diagnostics n = row_count;
  return n;
end $$;


--
-- Name: queue_access_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_access_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; new_id uuid; kind_key text; fmt constant text := 'FMDay DD Mon YYYY HH24:MI';
begin
  if not email_automation_enabled() then return 0; end if;
  for r in
    select pa.profile_id as uid, e.cohort_id, c.name as cohort_name, g.timezone as tz,
           coalesce(a.opens_at_override, c.access_opens_at) as opens, coalesce(a.closes_at_override, c.access_closes_at) as closes
    from cohort_enrolments e
    join cohorts c on c.id = e.cohort_id
    join programmes g on g.id = c.programme_id
    join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    left join learner_access a on a.participant_id = e.participant_id and a.cohort_id = e.cohort_id
    where pa.status <> 'withdrawn' and not coalesce(a.suspended, false) and not pr.email_opt_out and pr.status = 'active'
  loop
    if r.opens is not null and r.opens > now() and r.opens <= now() + interval '3 days' then
      kind_key := 'access_open:' || to_char(r.opens at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_opening_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.opens at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
    if r.closes is not null and r.closes > now() and r.closes <= now() + interval '7 days' and (r.opens is not null and r.opens <= now()) then
      kind_key := 'access_close:' || to_char(r.closes at time zone 'UTC', 'YYYYMMDDHH24MI');
      if not exists (select 1 from email_reminder_log l where l.kind = kind_key and l.ref_id = r.cohort_id and l.user_id = r.uid) then
        new_id := _enqueue_email(r.uid, 'access_closing_reminder', jsonb_build_object('cohort_name', r.cohort_name,
          'access_date', to_char(r.closes at time zone r.tz, fmt) || ' (' || r.tz || ')'), now(), 'reminder:access', null);
        insert into email_reminder_log(kind, ref_id, user_id) values (kind_key, r.cohort_id, r.uid) on conflict do nothing;
        if new_id is not null then n := n + 1; end if;
      end if;
    end if;
  end loop;
  return n;
end $$;


--
-- Name: queue_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_reminders() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r record; n int := 0; new_id uuid;
begin
  if not email_automation_enabled() then return 0; end if;
  -- Sessions starting in the next 24 hours (not cancelled), for enrolled participants who have not opted out.
  for r in
    select s.id as ref, pa.profile_id as uid, cs.title, s.starts_at, s.mode, s.venue, s.meeting_url, c.name as cohort_name
    from session_schedules s join curriculum_sessions cs on cs.id = s.curriculum_session_id join cohorts c on c.id = s.cohort_id
    join cohort_enrolments e on e.cohort_id = s.cohort_id join participants pa on pa.id = e.participant_id
    join profiles pr on pr.id = pa.profile_id
    where s.status in ('scheduled', 'rescheduled') and s.starts_at > now() and s.starts_at <= now() + interval '24 hours'
      and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (cs.track_id is null or cs.track_id = e.track_id)
      and not exists (select 1 from email_reminder_log l where l.kind = 'session' and l.ref_id = s.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'session_reminder', jsonb_build_object('session_title', r.title,
      'session_date', to_char(r.starts_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY'), 'session_time', to_char(r.starts_at at time zone 'Africa/Nairobi', 'HH24:MI') || ' EAT',
      'session_mode', r.mode::text, 'session_place', coalesce(case when r.mode = 'physical' then 'Venue: ' || r.venue else 'Meeting link: ' || coalesce(r.meeting_url, 'will be shared by your trainer') end, ''), 'cohort_name', r.cohort_name), now(), 'reminder:session', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('session', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  -- Assignments due in the next 48 hours that the participant has not submitted.
  for r in
    select a.id as ref, pa.profile_id as uid, a.title, a.due_at, c.name as cohort_name
    from assignments a join cohorts c on c.id = a.cohort_id join cohort_enrolments e on e.cohort_id = a.cohort_id
    join participants pa on pa.id = e.participant_id join profiles pr on pr.id = pa.profile_id
    where a.due_at > now() and a.due_at <= now() + interval '48 hours' and pa.status <> 'withdrawn' and not pr.email_opt_out
      and (a.track_id is null or a.track_id = e.track_id)
      and not exists (select 1 from submissions sb where sb.assignment_id = a.id and sb.participant_id = pa.id)
      and (not exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id) or exists (select 1 from assignment_recipients ar where ar.assignment_id = a.id and ar.participant_id = pa.id))
      and not exists (select 1 from email_reminder_log l where l.kind = 'assignment' and l.ref_id = a.id and l.user_id = pa.profile_id)
  loop
    new_id := _enqueue_email(r.uid, 'assignment_reminder', jsonb_build_object('assignment_title', r.title,
      'due_date', to_char(r.due_at at time zone 'Africa/Nairobi', 'FMDay DD Mon YYYY HH24:MI') || ' EAT', 'cohort_name', r.cohort_name), now(), 'reminder:assignment', null);
    insert into email_reminder_log(kind, ref_id, user_id) values ('assignment', r.ref, r.uid) on conflict do nothing;
    if new_id is not null then n := n + 1; end if;
  end loop;
  return n;
end $$;


--
-- Name: record_file_scan(text, text, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_file_scan(p_bucket text, p_name text, p_updated_at timestamp with time zone, p_result text, p_engine text DEFAULT NULL::text, p_detail text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare s storage_file_scans; final text;
begin
  if p_result not in ('clean', 'infected', 'error') then raise exception 'Result must be clean, infected or error'; end if;
  select * into s from storage_file_scans where bucket_id = p_bucket and object_name = p_name for update;
  if not found then raise exception 'File not in the scan queue'; end if;
  insert into storage_file_scan_log(bucket_id, object_name, object_updated_at, result, engine, detail)
  values (p_bucket, p_name, p_updated_at, p_result, left(p_engine, 100), left(p_detail, 500));
  if s.object_updated_at <> p_updated_at then return 'superseded'; end if;   -- the file was replaced meanwhile; the new version is queued
  final := case p_result when 'error' then (case when s.attempts >= 3 then 'scan_failed' else 'pending' end) else p_result end;
  update storage_file_scans set status = final, scanned_at = case when p_result = 'error' then scanned_at else now() end,
         engine = coalesce(left(p_engine, 100), engine), detail = left(p_detail, 500), claimed_at = null
  where bucket_id = p_bucket and object_name = p_name;
  if final = 'infected' and s.uploaded_by is not null then
    insert into notifications(user_id, kind, title, body) values (s.uploaded_by, 'message', 'A file you uploaded was blocked',
      'Our virus check found a problem with ' || left(regexp_replace(p_name, '^.*/', ''), 100) || '. It cannot be opened. Please upload a clean copy.');
  end if;
  return final;
end $$;


--
-- Name: render_text(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.render_text(t text, v jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
declare k text; val text; out text := t;
begin
  for k, val in select * from jsonb_each_text(v) loop out := replace(out, '{{' || k || '}}', coalesce(val, '')); end loop;
  if out ~ '\{\{[a-z_]+\}\}' then raise exception 'Unresolved placeholder in template: %', (regexp_match(out, '\{\{[a-z_]+\}\}'))[1]; end if;
  return out;
end $$;


--
-- Name: requeue_stuck_emails(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_stuck_emails() RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with u as (update email_outbox set status = 'queued' where status = 'sending' and claimed_at < now() - interval '15 minutes' and attempts < 3 returning 1) select count(*)::int from u $$;


--
-- Name: review_curriculum_topic(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_curriculum_topic(p_id uuid, p_decision text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  actor uuid := auth.uid();
  p curriculum_topic_proposals;
  c text := nullif(btrim(p_comment), '');
  new_state topic_status;
begin
  if actor is null or not can_approve_curriculum() then
    raise exception 'Only the Founder, Co-Founder or a Super Administrator can approve or reject curriculum topics';
  end if;
  if p_decision is null or p_decision not in ('approve', 'reject', 'reopen') then raise exception 'The decision must be approve, reject or reopen'; end if;
  if c is not null and length(c) > 1000 then raise exception 'The comment is too long (1000 characters at most)'; end if;

  select * into p from curriculum_topic_proposals where id = p_id for update;
  if not found then raise exception 'Topic not found'; end if;

  if p_decision = 'reopen' then
    if p.status <> 'rejected' then raise exception 'Only a rejected topic can be reconsidered (this one is %)', p.status; end if;
    new_state := 'pending';
  else
    if p.status <> 'pending' then raise exception 'Only a pending topic can be approved or rejected (this one is %)', p.status; end if;
    if p_decision = 'reject' and c is null then raise exception 'Give a reason when rejecting a topic'; end if;
    new_state := case when p_decision = 'approve' then 'approved'::topic_status else 'rejected'::topic_status end;
  end if;

  perform set_config('dira.topic_review', 'on', true);
  update curriculum_topic_proposals set status = new_state,
    reviewed_by = case when new_state = 'pending' then null else actor end,
    reviewed_at = case when new_state = 'pending' then null else now() end,
    reviewer_comment = case when new_state = 'pending' then null else c end
  where id = p.id;
  insert into curriculum_topic_events(proposal_id, from_status, to_status, actor_id, comment) values (p.id, p.status, new_state, actor, c);
  insert into audit_logs(actor_id, table_name, row_id, action, old_data, new_data)
    values (actor, 'curriculum_topic_proposals', p.id::text, 'curriculum_topic_' || case p_decision when 'approve' then 'approved' when 'reject' then 'rejected' else 'reopened' end,
            jsonb_build_object('status', p.status), jsonb_build_object('status', new_state, 'title', p.title, 'session_id', p.session_id, 'comment', c, 'decided_at', now()));
  perform set_config('dira.topic_review', 'off', true);
  return jsonb_build_object('status', new_state);
end $$;


--
-- Name: revoke_certificate(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_certificate(p_certificate uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare pprofile uuid; n int;
begin
  if coalesce(app_role() not in ('super_admin', 'founder', 'co_founder', 'programme_director'), true) then raise exception 'Only a super administrator or programme director can revoke certificates'; end if;
  if p_reason is null or length(trim(p_reason)) < 5 then raise exception 'A written reason is required'; end if;
  perform set_config('app.certificate_fn', '1', true);
  update certificates set revoked = true, revoked_at = now(), revoked_by = auth.uid(), revoked_reason = trim(p_reason)
    where id = p_certificate and not revoked;
  get diagnostics n = row_count;  -- PERFORM would overwrite FOUND, so count rows explicitly
  perform set_config('app.certificate_fn', '', true);
  if n = 0 then raise exception 'Certificate not found or already revoked'; end if;
  select p.profile_id into pprofile from certificates c join participants p on p.id = c.participant_id where c.id = p_certificate;
  insert into notifications(user_id, kind, title, body) values (pprofile, 'certificate', 'A certificate was withdrawn', 'Please contact the programme team if you have questions.');
end $$;


