    CONSTRAINT safeguarding_records_resolution_check CHECK (((resolution IS NULL) OR (length(resolution) <= 2000))),
    CONSTRAINT safeguarding_records_source_check CHECK ((source = ANY (ARRAY['manual'::text, 'raised_by_staff'::text, 'connect_report'::text, 'connect_safety_report'::text]))),
