--
-- Name: v_application_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_application_funnel WITH (security_invoker='true') AS
 SELECT (status)::text AS status,
    (count(*))::integer AS total
   FROM public.applications
  WHERE (status <> 'draft'::public.application_status)
  GROUP BY status;


--
-- Name: v_attendance_by_participant; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_attendance_by_participant WITH (security_invoker='true') AS
 SELECT participant_id,
    (count(*) FILTER (WHERE (status <> 'excused'::public.attendance_status)))::integer AS counted,
    (count(*) FILTER (WHERE (status = ANY (ARRAY['present'::public.attendance_status, 'late'::public.attendance_status]))))::integer AS attended,
        CASE
            WHEN (count(*) FILTER (WHERE (status <> 'excused'::public.attendance_status)) = 0) THEN NULL::numeric
            ELSE round(((100.0 * (count(*) FILTER (WHERE (status = ANY (ARRAY['present'::public.attendance_status, 'late'::public.attendance_status]))))::numeric) / (count(*) FILTER (WHERE (status <> 'excused'::public.attendance_status)))::numeric), 1)
        END AS rate_percent
   FROM public.attendance a
  GROUP BY participant_id;


--
-- Name: v_cohort_capacity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_cohort_capacity AS
SELECT
    NULL::uuid AS cohort_id,
    NULL::text AS name,
    NULL::integer AS capacity,
    NULL::integer AS enrolled;


--
-- Name: v_course_progress; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_course_progress WITH (security_invoker='true') AS
 SELECT course_id,
    participant_id,
    (( SELECT count(*) AS count
           FROM (public.course_lessons l
             JOIN public.course_modules m ON ((m.id = l.module_id)))
          WHERE (m.course_id = e.course_id)))::integer AS lessons_total,
    (( SELECT count(*) AS count
           FROM ((public.lesson_progress lp
             JOIN public.course_lessons l ON ((l.id = lp.lesson_id)))
             JOIN public.course_modules m ON ((m.id = l.module_id)))
          WHERE ((m.course_id = e.course_id) AND (lp.participant_id = e.participant_id))))::integer AS lessons_done
   FROM public.course_enrolments e;


--
-- Name: v_session_topics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_session_topics AS
 SELECT id AS session_id,
    COALESCE(( SELECT array_agg(p.title ORDER BY p.reviewed_at, p.title) AS array_agg
           FROM public.curriculum_topic_proposals p
          WHERE ((p.session_id = cs.id) AND (p.status = 'approved'::public.topic_status))), '{}'::text[]) AS approved_topics,
    COALESCE(( SELECT array_agg(u.topic ORDER BY u.n) AS array_agg
           FROM unnest(cs.topics) WITH ORDINALITY u(topic, n)
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM public.curriculum_topic_proposals p
                  WHERE ((p.session_id = cs.id) AND (lower(btrim(p.title)) = lower(btrim(u.topic))) AND (p.status = ANY (ARRAY['approved'::public.topic_status, 'rejected'::public.topic_status]))))))), '{}'::text[]) AS awaiting_topics
   FROM public.curriculum_sessions cs;


--
-- Name: v_track_enrolment; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_track_enrolment WITH (security_invoker='true') AS
 SELECT e.cohort_id,
    t.id AS track_id,
    t.name AS track_name,
    (count(*))::integer AS participants
   FROM (public.cohort_enrolments e
     JOIN public.tracks t ON ((t.id = e.track_id)))
  GROUP BY e.cohort_id, t.id, t.name;


--
-- Name: v_unplaced_participants; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_unplaced_participants WITH (security_invoker='true') AS
 SELECT p.id AS participant_id,
    p.participant_no,
    pr.first_name,
    pr.last_name
   FROM (public.participants p
     JOIN public.profiles pr ON ((pr.id = p.profile_id)))
  WHERE ((p.status = ANY (ARRAY['enrolled'::public.participant_status, 'active'::public.participant_status])) AND (NOT (EXISTS ( SELECT 1
           FROM (public.cohort_enrolments e
             JOIN public.cohorts c ON ((c.id = e.cohort_id)))
          WHERE ((e.participant_id = p.id) AND (NOT c.archived))))));


